import { I, dish } from "./catalog-kit.ts";
import type { Recipe, RecipeSource } from "./types";

const desserts365: RecipeSource = {
  book: "365 Desserts",
  author: "Anonymous",
  year: 1900,
  era: "1900s",
  archiveId: "365dessertsdesse00nels",
  credit: "365 Desserts: A Dessert for Every Day in the Year (G.W. Jacobs, 1900). Internet Archive 365dessertsdesse00nels. Public domain.",
};

function h(
  id: string,
  name: string,
  cuisine: string,
  tags: string[],
  protein: Recipe["protein"],
  plate: Recipe["plate"],
  minutes: number,
  description: string,
  ingredients: Recipe["ingredients"],
  steps: string[],
  nutrition: Recipe["nutrition"],
): Recipe {
  return dish({
    id, name, cuisine, description, minutes, protein, plate,
    tags: Array.from(new Set(["vintage", "book-365-desserts", "era-1900s", ...tags])),
    ingredients, steps, nutrition, source: desserts365,
  });
}

/** 365 Desserts (apr-jun), rebuilt exactly from the Internet Archive page images: printed names, printed ingredient order and amounts, verbatim method. Free core. */
export const DESSERTS_365_APR_JUN_RECIPES: Recipe[] = [
  h('ds-apr-01-duchess-cake-with-raspberry-filling', 'Duchess Cake with Raspberry Filling', 'American', ["month-april", "day-01"], 'eggs', 'dessert', 45, 'Put 1/2 pt. of water, 2 ozs. butter on to boil, then add 4 ozs. flour; stir until you have a thick paste, take from the fire and add 1 at a time, 4 eggs, mixing and heating each before the other is added.', [I('water', 0.5, 'pt', 'Pantry'), I('butter', 2, 'ozs', 'Dairy & Eggs'), I('flour', 4, 'ozs', 'Pantry'), I('eggs', 4, '', 'Dairy & Eggs'), I('egg (beaten)', 1, '', 'Dairy & Eggs'), I('raspberry jam', 1, '', 'Produce'), I('soft icing', 1, '', 'Pantry')], ['Put 1/2 pt. of water, 2 ozs. butter on to boil, then add 4 ozs. flour; stir until you have a thick paste, take from the fire and add 1 at a time, 4 eggs, mixing and heating each before the other is added.', 'Line baking pans with greased paper and take about 1/2 tablespoonful of the mixture and place it in an oval form, being careful that they do not touch each other; brush them over with beaten egg and bake in a moderate oven for at least 30 or 35 minutes.', 'When they are done they will be very light and hollow.', 'Take them from the oven, make a hole through the middle and fill the inside with raspberry jam.', 'Ice the tops with soft icing and when cold they are ready to serve.—From “Table Talk,” Phila.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-03-mulled-rice', 'Mulled Rice', 'American', ["month-april", "day-03"], 'eggs', 'dessert', 45, 'Take a large cup of rice, wash and soak well; put it on the fire with 2 qts. of milk, let it cook slowly from 3 to 4 hours until it becomes a perfect cream.', [I('rice', 1, 'large cup', 'Pantry'), I('milk', 2, 'qts', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('white sugar', 1, 'cup', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('wine', 1, 'glass', 'Pantry'), I('little nutmeg', 1, '', 'Herbs & Spices')], ['Take a large cup of rice, wash and soak well; put it on the fire with 2 qts. of milk, let it cook slowly from 3 to 4 hours until it becomes a perfect cream.', 'Make a sauce of a cup of white sugar, beaten thoroughly into 2 eggs and a glass of wine.', 'Serve the rice hot ; pour the sauce over it and grate a little nutmeg over the top.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-04-claret-punch', 'Claret Punch', 'American', ["month-april", "day-04"], 'veg', 'dessert', 45, 'Squeeze the juice from a lemon, cut up the rind and cover with 1 cup of granulated sugar.', [I('lemon', 1, '', 'Produce'), I('granulated sugar', 1, 'cup', 'Pantry'), I('claret', 1, 'cup', 'Pantry'), I('pineapple syrup', 0.5, 'cup', 'Produce'), I('soda', 1, 'bottle', 'Pantry'), I('sugar (to taste)', 1, '', 'Pantry')], ['Squeeze the juice from a lemon, cut up the rind and cover with 1 cup of granulated sugar.', 'Let it stand for 1/2 hour.', 'Mix with the juice and stir until the sugar is dissolved.', 'Add 1 cup of claret, and let it stand another 1/2 hour; strain, add another cup of claret, 1/2 cup of pineapple syrup and if desired, 1 bottle of soda.', 'Sweeten to taste and serve very cold.—From “Table Talk,” Phila.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-05-frosted-apples', 'Frosted Apples', 'American', ["month-april", "day-05"], 'eggs', 'dessert', 45, 'Peel some pippins, stew in a thin syrup till they become tender, but be careful they do not break.', [I('egg', 1, '', 'Dairy & Eggs'), I('sugar', 1, '', 'Pantry')], ['Peel some pippins, stew in a thin syrup till they become tender, but be careful they do not break.', 'Dip in the white of an egg that has been whipped to a stiff froth and sift powdered sugar over them thickly.', 'Place in a cool oven to candy and serve in a glass dish.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-06-washington-pie-with-molasses-filling', 'Washington Pie with Molasses Filling', 'American', ["month-april", "day-06"], 'eggs', 'dessert', 45, 'Beat the yolks of 2 eggs until light, add to them 1/2 a cup of light brown sugar and beat until creamy.', [I('eggs', 2, '', 'Dairy & Eggs'), I('light brown sugar', 0.5, 'cup', 'Pantry'), I('soda', 1, 'teaspoonful', 'Pantry'), I('hot water (a little)', 1, '', 'Pantry'), I('sour cream', 0.25, 'cup', 'Dairy & Eggs'), I('New Orleans Molasses', 0.5, 'cup', 'Pantry'), I('cinnamon', 0.5, 'teaspoonful', 'Herbs & Spices'), I('lemon peel (a grating)', 1, '', 'Produce'), I('flour', 1.5, 'cups', 'Pantry'), I('paste', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs'), I('water', 1, '', 'Pantry'), I('lemon juice', 1, 'teaspoonful', 'Produce'), I('confectioner’s sugar', 1, '', 'Pantry')], ['Beat the yolks of 2 eggs until light, add to them 1/2 a cup of light brown sugar and beat until creamy.', 'Dissolve a teaspoonful of soda in a little hot water; add it to 1/4 cup of sour cream and stir this into 1/2 a cup of New Orleans Molasses.', 'Mix well with the eggs and sugar; add 1/2 teaspoonful of cinnamon, a grating of lemon peel and 1 1/2 cups of flour.', 'Beat well, stir in the whites of the eggs beaten to a stiff, dry froth and turn at once into an oblong tin lined with paste.', 'Bake 30 minutes in a moderate oven.', 'When cool ice with the following: Break the white of 1 egg into a bowl; add 1/2 the white in water and 1 teaspoonful of lemon juice ; stir in confectioner’s sugar until it pours thickly from a spoon.', 'Beat until perfectly smooth.', 'Ice the pie and stand away to harden.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-07-cocoanut-bread-pudding', 'Cocoanut Bread Pudding', 'American', ["month-april", "day-07"], 'eggs', 'dessert', 45, 'Cover 1 cup of cocoanut with 1 quart of milk and soak 2 hours ; add 2 cups of bread crumbs and 3 eggs beaten light without separating.', [I('cocoanut', 1, 'cup', 'Produce'), I('milk', 1, 'quart', 'Dairy & Eggs'), I('bread crumbs', 2, 'cups', 'Pantry'), I('eggs', 3, '', 'Dairy & Eggs')], ['Cover 1 cup of cocoanut with 1 quart of milk and soak 2 hours ; add 2 cups of bread crumbs and 3 eggs beaten light without separating.', 'Mix well, turn into a greased pudding dish and bake 3/4 of an hour in a moderate oven.', 'Serve cold with hard or any sauce.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-08-spanish-puffs', 'Spanish Puffs', 'American', ["month-april", "day-08"], 'eggs', 'dessert', 45, 'One cup of boiled milk, 1 cup of flour, 4 eggs, boil the milk well, add the flour and stir until very smooth; add the eggs, 1 at a time, do not beat but stir them in well.', [I('boiled milk', 1, 'cup', 'Dairy & Eggs'), I('flour', 1, 'cup', 'Pantry'), I('eggs', 4, '', 'Dairy & Eggs'), I('lard', 1, '', 'Meat & Seafood'), I('maple syrup', 1, '', 'Pantry')], ['One cup of boiled milk, 1 cup of flour, 4 eggs, boil the milk well, add the flour and stir until very smooth; add the eggs, 1 at a time, do not beat but stir them in well.', 'Drop in boiling lard and fry.', 'Serve with maple syrup.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-09-a-sponge-pudding', 'A Sponge Pudding', 'American', ["month-april", "day-09"], 'veg', 'dessert', 45, 'Butter a mould; strew it thickly over with dried currants; fill the mould 3/4 full with small sponge cakes soaked in wine; fill it up with a rich custard, which must be cold.', [I('butter', 1, '', 'Dairy & Eggs'), I('dried currants', 1, '', 'Produce'), I('small sponge cakes', 1, '', 'Pantry'), I('wine', 1, '', 'Pantry'), I('rich custard', 1, '', 'Pantry')], ['Butter a mould; strew it thickly over with dried currants; fill the mould 3/4 full with small sponge cakes soaked in wine; fill it up with a rich custard, which must be cold.', 'Cover the mould carefully and boil an hour.', 'Turn out and serve with custard poured over it.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-10-plain-batter-pudding', 'Plain Batter Pudding', 'American', ["month-april", "day-10"], 'eggs', 'dessert', 45, 'One quart milk, 4 eggs, 6 spoonfuls of flour, a little salt; bake 20 minutes.', [I('milk', 1, 'quart', 'Dairy & Eggs'), I('eggs', 4, '', 'Dairy & Eggs'), I('flour', 6, 'spoonfuls', 'Pantry'), I('salt (a little)', 1, '', 'Herbs & Spices')], ['One quart milk, 4 eggs, 6 spoonfuls of flour, a little salt; bake 20 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-11-charlotte-russe', 'Charlotte Russe', 'American', ["month-april", "day-11"], 'eggs', 'dessert', 45, 'Cover 1/4 box of gelatine with 1/4 cup of cold water and let it stand for 1/2 hour; dissolve over hot water.', [I('gelatine', 0.25, 'box', 'Pantry'), I('cold water', 0.25, 'cup', 'Pantry'), I('milk', 1, 'cup', 'Dairy & Eggs'), I('granulated sugar', 1, 'cup', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs'), I('vanilla', 1, 'teaspoonful', 'Herbs & Spices'), I('cream', 1, 'pt', 'Dairy & Eggs'), I('stale macaroons', 1, '', 'Pantry')], ['Cover 1/4 box of gelatine with 1/4 cup of cold water and let it stand for 1/2 hour; dissolve over hot water.', 'Scald 1 cup of milk, add 1 cup of granulated sugar and stir until it is dissolved and the milk looks blue.', 'Beat 1 egg very light, add to the milk stirring all the while.', 'Take from the fire, add to the dissolved gelatine and stir again.', 'Flavor with 1 teaspoonful of vanilla and put away to cool.', 'Whip 1 pt. of cream, add it to the cooled custard, turn it into a mould previously wet with cold water and stand away to harden.', 'When ready to use, turn out and cover with stale macaroons.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-12-boiled-fruit-pudding', 'Boiled Fruit Pudding', 'American', ["month-april", "day-12"], 'beef', 'dessert', 45, 'One quart crushed wheat, 1 teaspoonful cinnamon, 1/2 teaspoonful cloves, 2 cupfuls sugar, 2 eggs, 1/2 lb. suet chopped fine, 1 teaspoonful cream of tartar, 1/2 teaspoonful soda, 1/4 cupful molasses, 1/2 lb. raisins chopped fine, citron and 2 teaspoonfuls extract of lemon.', [I('crushed wheat', 1, 'quart', 'Pantry'), I('cinnamon', 1, 'teaspoonful', 'Herbs & Spices'), I('cloves', 0.5, 'teaspoonful', 'Herbs & Spices'), I('sugar', 2, 'cupfuls', 'Pantry'), I('eggs', 2, '', 'Dairy & Eggs'), I('suet chopped fine', 0.5, 'lb', 'Meat & Seafood'), I('cream of tartar', 1, 'teaspoonful', 'Dairy & Eggs'), I('soda', 0.5, 'teaspoonful', 'Pantry'), I('molasses', 0.25, 'cupful', 'Pantry'), I('raisins chopped fine', 0.5, 'lb', 'Produce'), I('citron', 1, '', 'Produce'), I('extract of lemon', 2, 'teaspoonfuls', 'Herbs & Spices')], ['One quart crushed wheat, 1 teaspoonful cinnamon, 1/2 teaspoonful cloves, 2 cupfuls sugar, 2 eggs, 1/2 lb. suet chopped fine, 1 teaspoonful cream of tartar, 1/2 teaspoonful soda, 1/4 cupful molasses, 1/2 lb. raisins chopped fine, citron and 2 teaspoonfuls extract of lemon.', 'Boil 2 hours.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-13-half-hour-pudding', 'Half Hour Pudding', 'American', ["month-april", "day-13"], 'eggs', 'dessert', 45, 'Boil 1 1/2 pts. of milk, pour it over as many stale pieces of bread as it will soften; let it stand 10 minutes, and add 1 unbeaten egg, 1 tablespoonful of sugar, a little butter, salt and nutmeg, 1 teaspoonful of cream of tartar, 1/2 teaspoonful of soda; beat all well together and add the rest of the milk, then stir in 1/2 cup of currants dusted with a little flour.', [I('milk', 1.5, 'pts', 'Dairy & Eggs'), I('stale pieces of bread', 1, '', 'Pantry'), I('unbeaten egg', 1, '', 'Dairy & Eggs'), I('sugar', 1, 'tablespoonful', 'Pantry'), I('butter (a little)', 1, '', 'Dairy & Eggs'), I('salt', 1, '', 'Herbs & Spices'), I('nutmeg', 1, '', 'Herbs & Spices'), I('cream of tartar', 1, 'teaspoonful', 'Dairy & Eggs'), I('soda', 0.5, 'teaspoonful', 'Pantry'), I('currants', 0.5, 'cup', 'Produce'), I('flour (a little)', 1, '', 'Pantry')], ['Boil 1 1/2 pts. of milk, pour it over as many stale pieces of bread as it will soften; let it stand 10 minutes, and add 1 unbeaten egg, 1 tablespoonful of sugar, a little butter, salt and nutmeg, 1 teaspoonful of cream of tartar, 1/2 teaspoonful of soda; beat all well together and add the rest of the milk, then stir in 1/2 cup of currants dusted with a little flour.', 'Pour into a buttered bowl and steam 1/2 hour.', 'Serve with a sauce.', 'It is very nice without the currants.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-14-banana-fritters', 'Banana Fritters', 'American', ["month-april", "day-14"], 'eggs', 'dessert', 45, 'Cut 8 bananas in pieces.', [I('bananas', 8, '', 'Produce'), I('flour', 1, 'cup', 'Pantry'), I('eggs', 2, '', 'Dairy & Eggs'), I('cold water', 0.6667, 'cup', 'Pantry'), I('olive oil', 1, 'tablespoonful', 'Pantry'), I('baking powder', 1, 'level teaspoonful', 'Pantry'), I('lard', 1, '', 'Meat & Seafood'), I('powdered sugar', 1, '', 'Pantry')], ['Cut 8 bananas in pieces.', 'Make a French fritter batter as follows: Put 1 cup of flour into a bowl; beat the yolks of 2 eggs, add to them 2/3 of a cup of cold water, then add this gradually to the flour, stirring all the while.', 'It should form a smooth but rather liquid paste, but at the same time have enough consistency to adhere to the bananas ; add a tablespoonful of olive oil, the well-beaten whites of the eggs and a level teaspoonful of baking powder.', 'Mix carefully ; cover the bananas with this paste and drop them into smoking hot lard and when a bright golden color, drain, sprinkle with powdered sugar and serve.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-15-orange-bavarian-cream', 'Orange Bavarian Cream', 'American', ["month-april", "day-15"], 'veg', 'dessert', 45, 'Cover 3/4 of box of gelatine with 1/2 cup cold water; soak it for 1/2 hour; stir 1 lb. sugar into 1 qt. of orange juice until the sugar is thoroughly dissolved, then strain this into a basin.', [I('gelatine', 0.75, 'box', 'Pantry'), I('cold water', 0.5, 'cup', 'Pantry'), I('sugar', 1, 'lb', 'Pantry'), I('orange juice', 1, 'qt', 'Produce'), I('cream whipped', 1.5, 'pts', 'Dairy & Eggs')], ['Cover 3/4 of box of gelatine with 1/2 cup cold water; soak it for 1/2 hour; stir 1 lb. sugar into 1 qt. of orange juice until the sugar is thoroughly dissolved, then strain this into a basin.', 'Stand the gelatine over a kettle of hot water until thoroughly melted ; strain it into the orange juice and stir carefully until the mixture begins to congeal ; then add 1 1/2 pts. cream whipped to a stiff froth.', 'This must be stirred very carefully from the bottom and sides of the pan until the mixture is one color; that is until all streaks of yellow disappear.', 'Turn into your pudding mould and stand away over night.', 'This may be served perfectly plain, or may be served with whipped cream heaped around it.—From “Table Talk,” Phila.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-16-maizura-pudding', 'Maizura Pudding', 'American', ["month-april", "day-16"], 'eggs', 'dessert', 45, 'Four tablespoonfuls maizura stirred into 2 eggs, and milk enough to make it smooth.', [I('maizura', 4, 'tablespoonfuls', 'Pantry'), I('eggs', 2, '', 'Dairy & Eggs'), I('milk', 1, 'qt', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs'), I('sugar', 1, '', 'Pantry')], ['Four tablespoonfuls maizura stirred into 2 eggs, and milk enough to make it smooth.', 'Heat 1 qt. milk in a double boiler, and just before it boils stir in the above, constantly stirring until it thickens.', 'Remove from the fire and flavor.', 'To be eaten cold with cream or milk and sugar.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-17-fruit-balls', 'Fruit Balls', 'American', ["month-april", "day-17"], 'beef', 'dessert', 45, 'Chop 2 ozs. of suet rather fine, having first freed it from shreds; add to this twice the quantity of bread crumbs, that is after you have chopped the suet ; take twice the quantity of crumbs, add the white of 1 egg, 1/2 cup of chopped raisins, 1/2 cup of currants and a few pieces of citron.', [I('suet rather fine', 2, 'ozs', 'Meat & Seafood'), I('bread crumbs', 1, '', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs'), I('chopped raisins', 0.5, 'cup', 'Produce'), I('currants', 0.5, 'cup', 'Produce'), I('citron', 1, '', 'Produce'), I('brandy', 1, '', 'Pantry'), I('eggs', 1, '', 'Dairy & Eggs')], ['Chop 2 ozs. of suet rather fine, having first freed it from shreds; add to this twice the quantity of bread crumbs, that is after you have chopped the suet ; take twice the quantity of crumbs, add the white of 1 egg, 1/2 cup of chopped raisins, 1/2 cup of currants and a few pieces of citron.', 'If it is now moist, form into balls the size of a walnut.', 'If they are at all dry, add the white of another egg.', 'Have ready a kettle of boiling water, drop the balls in and cook slowly until they come to the surface ; lift carefully with a skimmer, dish and pour over them a rich brandy sauce made with the yolks of the eggs.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-18-nesselrode-pudding', 'Nesselrode Pudding', 'American', ["month-april", "day-18"], 'eggs', 'dessert', 45, 'Shell 3 cups of French or Italian chestnuts.', [I('French or Italian chestnuts', 3, 'cups', 'Produce'), I('French candied fruit', 1, 'pound', 'Produce'), I('sherry', 1, 'wine-glass', 'Pantry'), I('sugar', 2, 'cups', 'Pantry'), I('water', 1, 'cup', 'Pantry'), I('eggs', 4, '', 'Dairy & Eggs'), I('cream', 1, 'pint', 'Dairy & Eggs'), I('vanilla', 1, 'teaspoonful', 'Herbs & Spices')], ['Shell 3 cups of French or Italian chestnuts.', 'Carefully remove the brown skin; then simmer for 30 minutes, or until soft.', 'Drain, press through a colander, cut 1 pound of French candied fruit in small pieces and cover with one wine-glass of sherry.', 'Boil 2 cups of sugar and 1 cup of water for 15 minutes.', 'Beat the yolks of 4 eggs very light; then beat them into the boiling syrup.', 'Stir over the fire until it again reaches the boiling point, then remove and beat while cooling, adding 1 pint of cream whipped to a stiff froth, the fruit, wine and 1 teaspoonful of vanilla.', 'Turn into a freezer and freeze.', 'When frozen, pack and stand away to ripen.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-19-arrowroot-pudding', 'Arrowroot Pudding', 'American', ["month-april", "day-19"], 'eggs', 'dessert', 45, 'Mix 4 spoonfuls of arrowroot with a teacup full of new milk, then boil nearly a quart of milk and stir in the arrowroot.', [I('arrowroot', 4, 'spoonfuls', 'Pantry'), I('new milk (a teacup full)', 1, '', 'Dairy & Eggs'), I('milk (nearly a quart)', 1, '', 'Dairy & Eggs'), I('well-beaten eggs', 2, '', 'Dairy & Eggs'), I('melted butter', 2, 'spoonfuls', 'Dairy & Eggs'), I('sugar (to taste)', 1, '', 'Pantry'), I('nutmeg (a little)', 1, '', 'Herbs & Spices')], ['Mix 4 spoonfuls of arrowroot with a teacup full of new milk, then boil nearly a quart of milk and stir in the arrowroot.', 'When nearly cold add 2 well-beaten eggs, 2 spoonfuls of melted butter, sugar to taste and a little nutmeg.', 'Bake about 20 minutes.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-20-german-toast', 'German Toast', 'American', ["month-april", "day-20"], 'eggs', 'dessert', 45, 'Cut the bread in rather thick slices, beat 2 eggs light without separating and add to them 1 pint of milk, heating all the while.', [I('bread', 1, '', 'Pantry'), I('eggs', 2, '', 'Dairy & Eggs'), I('milk', 1, 'pint', 'Dairy & Eggs'), I('butter', 1, '', 'Dairy & Eggs')], ['Cut the bread in rather thick slices, beat 2 eggs light without separating and add to them 1 pint of milk, heating all the while.', 'Grease a hot griddle or frying pan with butter; dip the bread in the milk and eggs and fry on both sides to a delicate brown.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-21-claret-jelly', 'Claret Jelly', 'American', ["month-april", "day-21"], 'veg', 'dessert', 45, 'A package of gelatine soaked in a pt. of cold water, juice of 3 lemons and grated peel of 1, a pint of claret, sugar to taste.', [I('gelatine', 1, 'package', 'Pantry'), I('cold water', 1, 'pt', 'Pantry'), I('lemons', 3, '', 'Produce'), I('claret', 1, 'pint', 'Pantry'), I('sugar (to taste)', 1, '', 'Pantry'), I('boiling water', 1, 'quart', 'Pantry')], ['A package of gelatine soaked in a pt. of cold water, juice of 3 lemons and grated peel of 1, a pint of claret, sugar to taste.', 'Pour over these a quart of boiling water ; stir until dissolved, and strain into moulds, previously wet with cold water.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-22-flourendines', 'Flourendines', 'American', ["month-april", "day-22"], 'eggs', 'dessert', 45, 'Boil 1/2 cup of rice in 2 qts. of water until tender, or for about 20 minutes; drain until thoroughly dry.', [I('rice', 0.5, 'cup', 'Pantry'), I('water', 2, 'qts', 'Pantry'), I('eggs', 4, '', 'Dairy & Eggs'), I('sugar', 0.5, 'cup', 'Pantry'), I('milk', 1, 'pt', 'Dairy & Eggs'), I('vanilla', 1, 'tablespoonful', 'Herbs & Spices'), I('good light paste', 1, '', 'Pantry'), I('seeded raisins', 1, '', 'Produce'), I('eggs', 2, '', 'Dairy & Eggs'), I('powdered sugar', 2, 'tablespoonfuls', 'Pantry')], ['Boil 1/2 cup of rice in 2 qts. of water until tender, or for about 20 minutes; drain until thoroughly dry.', 'Beat 4 eggs without separating, until light ; add 1/2 cup of sugar and beat again until light, then add 1 pt. of milk, 1 tablespoonful of vanilla and the boiled rice.', 'Line 2 pie dishes with good light paste, cover the bottom of the dishes with seeded raisins.', 'Fill with the rice mixture and bake in a quick oven about 30 minutes, or until the custard is solid.', 'Beat the whites of 2 eggs until light, add 2 tablespoonfuls of powdered sugar and beat again until very stiff.', 'Spread a thin covering of this mixture over the pie, dust with powdered sugar, put back in the oven and bake until a golden brown; serve when cold.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-23-chocolate-custard', 'Chocolate Custard', 'American', ["month-april", "day-23"], 'eggs', 'dessert', 45, 'Three ounces Baker’s chocolate, 3 pts. of milk, 4 tablespoonfuls white sugar, 2 tablespoonfuls brown sugar ; prepare a soft custard of the milk and the yolks of 5 eggs and the white of 1; dissolve the chocolate in a cup of warm milk and heat it to boiling point ; when cool, sweeten with the brown sugar and flavor with vanilla; pour the whole into a dish and cover with whites of the 5 eggs beaten stiff with a little sugar ; brown slightly and serve cold.', [I('Baker’s chocolate', 3, 'ounces', 'Pantry'), I('milk', 3, 'pts', 'Dairy & Eggs'), I('white sugar', 4, 'tablespoonfuls', 'Dairy & Eggs'), I('brown sugar', 2, 'tablespoonfuls', 'Pantry'), I('eggs', 5, '', 'Dairy & Eggs'), I('warm milk', 1, 'cup', 'Dairy & Eggs'), I('vanilla (to flavor)', 1, '', 'Herbs & Spices')], ['Three ounces Baker’s chocolate, 3 pts. of milk, 4 tablespoonfuls white sugar, 2 tablespoonfuls brown sugar ; prepare a soft custard of the milk and the yolks of 5 eggs and the white of 1; dissolve the chocolate in a cup of warm milk and heat it to boiling point ; when cool, sweeten with the brown sugar and flavor with vanilla; pour the whole into a dish and cover with whites of the 5 eggs beaten stiff with a little sugar ; brown slightly and serve cold.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-24-spanish-cream', 'Spanish Cream', 'American', ["month-april", "day-24"], 'eggs', 'dessert', 45, 'Put 1/3 of a box of gelatine to soak in 1/3 cup of cold water; separate 4 eggs, put 1 pint of milk in a farina boiler, beat the yolks of the eggs with 1/2 cup of sugar until light.', [I('gelatine', 0.3333, 'box', 'Pantry'), I('cold water', 0.3333, 'cup', 'Pantry'), I('eggs', 4, '', 'Dairy & Eggs'), I('milk', 1, 'pint', 'Dairy & Eggs'), I('sugar', 0.5, 'cup', 'Pantry'), I('boiling water', 0.75, 'cup', 'Pantry')], ['Put 1/3 of a box of gelatine to soak in 1/3 cup of cold water; separate 4 eggs, put 1 pint of milk in a farina boiler, beat the yolks of the eggs with 1/2 cup of sugar until light.', 'Add them to the hot milk, stir for a minute, take from the fire and stand aside to cool.', 'Beat the whites of the eggs to a stiff froth.', 'Add 3/4 of a cup of boiling water to the gelatine, strained, and the whites of the eggs ; stir all together and turn into a mould.', 'This should settle into 3 layers and is a very pretty and attractive pudding.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-25-lemon-custard', 'Lemon Custard', 'American', ["month-april", "day-25"], 'eggs', 'dessert', 45, 'Separate 3 eggs, beat the yolks and add gradually 1 cup of granulated sugar.', [I('eggs', 3, '', 'Dairy & Eggs'), I('granulated sugar', 1, 'cup', 'Pantry'), I('flour', 1, 'tablespoonful', 'Pantry'), I('milk', 0.5, 'pint', 'Dairy & Eggs'), I('lemon', 1, '', 'Produce')], ['Separate 3 eggs, beat the yolks and add gradually 1 cup of granulated sugar.', 'Put a rounding tablespoonful of flour into a bowl and add gradually, mixing all the while ; 1/2 pint of milk, add the grated yellow rind and juice of one lemon to the yolks and sugar.', 'Beat until thoroughly mixed.', 'Now add the milk and flour.', 'Stir until the sugar is dissolved.', 'Let it stand in a cold place 20 minutes and it is ready to use.—From “Table Talk,” Phila.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-26-cocoanut-pudding', 'Cocoanut Pudding', 'American', ["month-april", "day-26"], 'eggs', 'dessert', 45, 'One quart of milk, half a cocoanut grated, 4 eggs, a little salt and sugar to taste.', [I('milk', 1, 'quart', 'Dairy & Eggs'), I('cocoanut', 0.5, '', 'Produce'), I('eggs', 4, '', 'Dairy & Eggs'), I('salt (a little)', 1, '', 'Herbs & Spices'), I('sugar (to taste)', 1, '', 'Pantry')], ['One quart of milk, half a cocoanut grated, 4 eggs, a little salt and sugar to taste.', 'Bake in a quick oven about 30 minutes.', 'Serve with sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-27-pineapple-pie', 'Pineapple Pie', 'American', ["month-april", "day-27"], 'eggs', 'dessert', 45, 'Beat 1/2 cup of butter and a cup of sugar to a cream; add the yolks of 5 eggs and beat again, then add 1 good-sized pineapple, grated, 1 cup of sweet cream and the whites of the eggs beaten to a stiff froth.', [I('butter', 0.5, 'cup', 'Dairy & Eggs'), I('sugar', 1, 'cup', 'Pantry'), I('eggs', 5, '', 'Dairy & Eggs'), I('good-sized pineapple, grated', 1, '', 'Produce'), I('sweet cream', 1, 'cup', 'Dairy & Eggs'), I('light paste', 1, '', 'Pantry')], ['Beat 1/2 cup of butter and a cup of sugar to a cream; add the yolks of 5 eggs and beat again, then add 1 good-sized pineapple, grated, 1 cup of sweet cream and the whites of the eggs beaten to a stiff froth.', 'Line a deep pie dish with light paste, fill with the mixture and bake in a quick oven about 30 minutes.', 'If canned pineapple is used, 1/2 the given quantity of sugar will be sufficient.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-28-sultana-roll', 'Sultana Roll', 'American', ["month-april", "day-28"], 'eggs', 'dessert', 45, 'Make the ice cream as follows: Scald 1 pt. of milk; add 1 cup of sugar, 1 level tablespoonful of flour rubbed smooth with a little cold milk, and 1 egg beaten without separating.', [I('milk', 1, 'pt', 'Dairy & Eggs'), I('sugar', 1, 'cup', 'Pantry'), I('flour', 1, 'level tablespoonful', 'Pantry'), I('cold milk (a little)', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('salt', 1, 'salt spoonful', 'Herbs & Spices'), I('whipped cream', 1, 'qt', 'Dairy & Eggs'), I('vanilla', 1, 'tablespoonful', 'Herbs & Spices'), I('extract of almond', 1, 'tablespoonful', 'Herbs & Spices'), I('leaf green (to color)', 1, '', 'Pantry'), I('sultana raisins', 1, '', 'Produce'), I('brandy', 1, '', 'Pantry'), I('cream', 1, 'pt', 'Dairy & Eggs'), I('powdered sugar', 0.5, 'cup', 'Pantry'), I('vanilla', 1, 'teaspoonful', 'Herbs & Spices'), I('sugar', 1, 'cup', 'Pantry'), I('water', 0.25, 'cup', 'Pantry'), I('claret', 4, 'tablespoonfuls', 'Pantry')], ['Make the ice cream as follows: Scald 1 pt. of milk; add 1 cup of sugar, 1 level tablespoonful of flour rubbed smooth with a little cold milk, and 1 egg beaten without separating.', 'Cook 20 minutes, add 1 salt spoonful of salt, strain and cool, add 1 qt. of whipped cream, flavor with 1 tablespoonful of vanilla and 1 tablespoonful ex. of almond; color with leaf green and freeze.', 'When frozen, line a mould with the cream and sprinkle with sultana raisins, which have been soaked several hours in brandy.', 'Fill the centre of the mould with 1 pt. of cream whipped to a stiff, dry froth, sweetened with 1/2 of a cup of powdered sugar and flavored with 1 teaspoonful of vanilla.', 'Cover the mould, pack in ice and salt, and let stand for 2 hours.', 'Serve with claret sauce.', 'CLARET SAUCE.—Put 1 cup of sugar with 1/4 of a cup of water in a sauce pan over the fire; stir until the sugar is dissolved, then boil until it thickens slightly.', 'Cool and add 4 tablespoonfuls of claret.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-29-tapioca-cream-pudding', 'Tapioca Cream Pudding', 'American', ["month-april", "day-29"], 'eggs', 'dessert', 45, 'One cup of tapioca soaked over night in cold water, boil 1 qt. of milk and stir in the tapioca, boil 10 minutes, stirring all the time.', [I('tapioca', 1, 'cup', 'Pantry'), I('cold water', 1, '', 'Pantry'), I('milk', 1, 'qt', 'Dairy & Eggs'), I('cornstarch', 1, 'tablespoonful', 'Produce'), I('milk', 0.5, 'cup', 'Dairy & Eggs'), I('eggs', 4, '', 'Dairy & Eggs'), I('salt (a little)', 1, '', 'Herbs & Spices'), I('sugar (to taste)', 1, '', 'Pantry'), I('sugar', 2, 'tablespoonfuls', 'Pantry')], ['One cup of tapioca soaked over night in cold water, boil 1 qt. of milk and stir in the tapioca, boil 10 minutes, stirring all the time.', 'Dissolve 1 tablespoonful of cornstarch in 1/2 cup of milk, add the beaten yolks of 4 eggs and stir into the tapioca, add a little salt, sweeten to taste and boil up once.', 'Flavor to taste.', 'Beat the whites of 4 eggs and 2 tablespoonfuls of sugar; flavor, spread over the pudding and brown in oven.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-apr-30-bread-meringue', 'Bread Meringue', 'American', ["month-april", "day-30"], 'eggs', 'dessert', 45, 'Beat the yolks of 4 eggs light, add gradually 1 cup of granulated sugar, beating all the while, and the grated rind of one lemon.', [I('eggs', 4, '', 'Dairy & Eggs'), I('granulated sugar', 1, 'cup', 'Pantry'), I('lemon', 1, '', 'Produce'), I('bread crumbs', 1, 'pt', 'Pantry'), I('milk', 1, 'qt', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('powdered sugar', 4, 'tablespoonfuls', 'Pantry')], ['Beat the yolks of 4 eggs light, add gradually 1 cup of granulated sugar, beating all the while, and the grated rind of one lemon.', 'Mix 1 pt. of bread crumbs with 1 qt. of milk, pour this on the eggs and sugar.', 'Mix well, and bake in a moderate oven until stiff.', 'When done, make a meringue of the whites of 2 eggs and 4 tablespoonfuls of powdered sugar; put on the pudding and brown in a quick oven.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-01-lemon-pudding', 'Lemon Pudding', 'American', ["month-may", "day-01"], 'eggs', 'dessert', 45, 'Make a sponge cake of 6 eggs, 1/2 lb. of sugar, 6 ozs. of flour.', [I('sponge cake', 1, '', 'Pantry'), I('eggs', 6, '', 'Dairy & Eggs'), I('sugar', 0.5, 'lb', 'Pantry'), I('flour', 6, 'ozs', 'Pantry'), I('milk', 1, 'pt', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('cornstarch', 0.5, 'teaspoonful', 'Produce'), I('lemons', 2, '', 'Produce'), I('butter', 0.25, 'lb', 'Dairy & Eggs'), I('sugar (to taste)', 1, '', 'Pantry')], ['Make a sponge cake of 6 eggs, 1/2 lb. of sugar, 6 ozs. of flour.', 'Divide the latter in 3 parts and bake in jelly cake pans.', 'Let it cool, make a custard of a pt. of milk, 3 eggs, 1/2 teaspoonful of cornstarch, the juice and grated rind of 2 lemons, 1/4 of a lb. of butter and sugar to taste; split the cakes through the middle and divide the custard equally among the three.', 'Place the top of the cake on the custard and sprinkle sugar over.', 'Serve cold.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-02-huevos-chimbos', 'Huevos Chimbos', 'American', ["month-may", "day-02"], 'eggs', 'dessert', 45, 'The yolks of 10 eggs beaten very light and baked in shallow tins; cut it in squares and pour over it boiling syrup, made from sugar and water; leave it to simmer on top of the stove till it is well saturated, then put by to cool and when cool stick blanched almonds over it to ornament it.—“Table Talk.”', [I('eggs', 10, '', 'Dairy & Eggs'), I('sugar', 1, '', 'Pantry'), I('water', 1, '', 'Pantry'), I('almonds', 1, '', 'Produce')], ['The yolks of 10 eggs beaten very light and baked in shallow tins; cut it in squares and pour over it boiling syrup, made from sugar and water; leave it to simmer on top of the stove till it is well saturated, then put by to cool and when cool stick blanched almonds over it to ornament it.—“Table Talk.”'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-03-prince-albert-pudding', 'Prince Albert Pudding', 'American', ["month-may", "day-03"], 'eggs', 'dessert', 45, 'One-fourth lb. butter, 1/4 lb. sugar, 1/2 lb. raisins stoned, 2 eggs, 1/4 lb. flour.', [I('butter', 0.25, 'lb', 'Dairy & Eggs'), I('sugar', 0.25, 'lb', 'Pantry'), I('raisins stoned', 0.5, 'lb', 'Produce'), I('eggs', 2, '', 'Dairy & Eggs'), I('flour', 0.25, 'lb', 'Pantry'), I('lemon', 1, '', 'Produce')], ['One-fourth lb. butter, 1/4 lb. sugar, 1/2 lb. raisins stoned, 2 eggs, 1/4 lb. flour.', 'Beat the butter and sugar to a cream, add the raisins and stir in the flour very lightly; line your buttered mould with strips of candied lemon peel and steam 1 1/2 hours.', 'Serve with sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-04-creme-au-caramel', 'Creme Au Caramel', 'American', ["month-may", "day-04"], 'eggs', 'dessert', 45, 'Place upon the fire 6 tablespoonfuls of brown sugar, keeping it there until it becomes a caramel.', [I('brown sugar', 6, 'tablespoonfuls', 'Pantry'), I('boiled milk', 1, 'qt', 'Dairy & Eggs'), I('eggs', 4, '', 'Dairy & Eggs')], ['Place upon the fire 6 tablespoonfuls of brown sugar, keeping it there until it becomes a caramel.', 'When cold, pour over this 1 qt. of boiled milk and stir until quite smooth.', 'Pour over 4 eggs well beaten and stir over the fire until it thickens.', 'Serve cold.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-05-chocolate-mance', 'Chocolate Mance', 'American', ["month-may", "day-05"], 'veg', 'dessert', 45, 'One box of Cox’s gelatine dissolved in a pint of cold water, 3 pints of milk; put over to boil with one cup of French chocolate ; when the milk is just scalded, pour in the gelatine, sweeten to taste, boil 5 minutes, then take from the fire, flavor with vanilla, pour into moulds, when cold, serve with powdered sugar and cream.', [I('Cox’s gelatine dissolved', 1, 'box', 'Pantry'), I('cold water', 1, 'pint', 'Pantry'), I('milk', 3, 'pints', 'Dairy & Eggs'), I('French chocolate', 1, 'cup', 'Pantry'), I('vanilla (to flavor)', 1, '', 'Herbs & Spices'), I('sugar (to taste)', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs')], ['One box of Cox’s gelatine dissolved in a pint of cold water, 3 pints of milk; put over to boil with one cup of French chocolate ; when the milk is just scalded, pour in the gelatine, sweeten to taste, boil 5 minutes, then take from the fire, flavor with vanilla, pour into moulds, when cold, serve with powdered sugar and cream.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-06-minnie-s-rice-pudding', 'Minnie’s Rice Pudding', 'American', ["month-may", "day-06"], 'veg', 'dessert', 45, 'To twelve cups of milk, one cup of rice well washed.', [I('milk', 12, 'cups', 'Dairy & Eggs'), I('rice well washed', 1, 'cup', 'Pantry'), I('sugar (to taste)', 1, '', 'Pantry'), I('vanilla or nutmeg (to flavor)', 1, '', 'Herbs & Spices'), I('salt (a little)', 1, '', 'Herbs & Spices'), I('butter', 1, 'teaspoonful', 'Dairy & Eggs')], ['To twelve cups of milk, one cup of rice well washed.', 'Sweeten to taste, flavor with vanilla or nutmeg ; add a little salt and about a teaspoonful of butter.', 'Bake in a slow oven for three or four hours, stirring frequently until the last hour; then let it brown nicely.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-07-mysterious-pudding', 'Mysterious Pudding', 'American', ["month-may", "day-07"], 'eggs', 'dessert', 45, 'Two eggs and their weight in flour, butter and moist sugar.', [I('eggs', 2, '', 'Dairy & Eggs'), I('flour', 1, '', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('sugar', 1, '', 'Pantry'), I('carbonate of soda', 1, 'small teaspoonful', 'Pantry'), I('baking powder', 1, '', 'Pantry'), I('orange marmalade', 1, 'large dessertspoonful', 'Produce'), I('water', 1, '', 'Pantry')], ['Two eggs and their weight in flour, butter and moist sugar.', 'Beat the whites and yolks separately ; mix these ingredients well together; the butter and sugar first, then the yolks, the whites last; then add a small teaspoonful of carbonate of soda, or baking powder, and a large dessertspoonful of orange marmalade.', 'Pour the mixture into a buttered mould or basin, not more than 2/3 full, as it rises quickly.', 'Steam over boiling water 1 1/4 hrs. Everything depends on the cooking.', 'Serve with pudding sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-08-wine-custard', 'Wine Custard', 'American', ["month-may", "day-08"], 'veg', 'dessert', 45, 'Heat to 100 degrees 1 1/2 pts. of milk, add 1 1/2 tablespoonfuls each of sugar and cooking-sherry ; stir well and then add 1 1/2 tablespoonfuls of liquid rennet, stirring only enough to mix it with the milk.', [I('milk', 1.5, 'pts', 'Dairy & Eggs'), I('sugar', 1.5, 'tablespoonfuls', 'Pantry'), I('cooking-sherry', 1.5, 'tablespoonfuls', 'Pantry'), I('liquid rennet', 1.5, 'tablespoonfuls', 'Pantry')], ['Heat to 100 degrees 1 1/2 pts. of milk, add 1 1/2 tablespoonfuls each of sugar and cooking-sherry ; stir well and then add 1 1/2 tablespoonfuls of liquid rennet, stirring only enough to mix it with the milk.', 'Pour into a glass dish and it will be ready to serve in about 2 hours.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-09-orange-marmalade-pudding', 'Orange Marmalade Pudding', 'American', ["month-may", "day-09"], 'eggs', 'dessert', 45, 'One cup fine bread crumbs, 1/2 cup of sugar, 1 cup of milk or cream, 4 eggs, 2 teaspoonfuls butter, cup orange or other sweet marmalade; put the butter and sugar together, add the yolks well beaten ; the milk, bread crumbs and the whites whipped to a froth.', [I('fine bread crumbs', 1, 'cup', 'Pantry'), I('sugar', 0.5, 'cup', 'Pantry'), I('milk or cream', 1, 'cup', 'Dairy & Eggs'), I('eggs', 4, '', 'Dairy & Eggs'), I('butter', 2, 'teaspoonfuls', 'Dairy & Eggs'), I('orange or other sweet marmalade', 1, 'cup', 'Produce'), I('sweetened cream or custard', 1, '', 'Dairy & Eggs')], ['One cup fine bread crumbs, 1/2 cup of sugar, 1 cup of milk or cream, 4 eggs, 2 teaspoonfuls butter, cup orange or other sweet marmalade; put the butter and sugar together, add the yolks well beaten ; the milk, bread crumbs and the whites whipped to a froth.', 'Put a layer of this in the bottom of a well-buttered mould, spread thickly with some pretty stiff marmalade, orange is the best, then another layer of the mixture, and so on until the mould is full, having the custard mixture at the top.', 'Bake in a moderate oven about 1 hour, turn out of the mould upon a dish and serve with sweetened cream or custard.—From “Common Sense in the “Household,” by Marion Harland, Copyright 1880, 1892 by Charles “Scribner’s Sons.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-10-orange-sponge', 'Orange Sponge', 'American', ["month-may", "day-10"], 'eggs', 'dessert', 45, 'One ounce gelatine in 1 qt. water; strain and stand until it begins to thicken, then add whites of 3 eggs, the juice of 2 lemons and 1 large orange.', [I('gelatine', 1, 'ounce', 'Pantry'), I('water', 1, 'qt', 'Pantry'), I('eggs', 3, '', 'Dairy & Eggs'), I('lemons', 2, '', 'Produce'), I('large orange', 1, '', 'Produce')], ['One ounce gelatine in 1 qt. water; strain and stand until it begins to thicken, then add whites of 3 eggs, the juice of 2 lemons and 1 large orange.', 'Sweeten to the taste, beat all thoroughly and put in moulds.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-11-caramel-pudding-new', 'Caramel Pudding (New)', 'American', ["month-may", "day-11"], 'eggs', 'dessert', 45, 'Take 2 fancy moulds, each holding 1 1/2 pts., brush them lightly with butter, then stand them in pan of ice water.', [I('butter', 1, '', 'Dairy & Eggs'), I('granulated sugar', 1, 'cup', 'Pantry'), I('eggs', 8, '', 'Dairy & Eggs'), I('sugar', 0.5, 'cup', 'Pantry'), I('milk', 1, 'qt', 'Dairy & Eggs'), I('vanilla', 1, 'teaspoonful', 'Herbs & Spices')], ['Take 2 fancy moulds, each holding 1 1/2 pts., brush them lightly with butter, then stand them in pan of ice water.', 'Put 1 cup granulated sugar into a granite sauce pan; do not add a particle of water, but stir the sugar over the fire till it melts and is a strawcolored liquid ; now pour this into the moulds, turning them so that you have a thin coating of caramel all over the inside of the mould.', 'Now stand the moulds aside while you make the pudding.', 'Beat 8 eggs without separating, until light, add 1/2 cup of sugar and beat again; add 1 qt. milk and teaspoonful of vanilla; mix this thoroughly until the sugar is dissolved, turn it into the moulds, stand the moulds in a pan of hot water, cover them with paper and cook in a quick oven until jellylike and firm.', 'Try by running a spoon in the centre; if it comes out milky they are not done.', 'When done, take them out, stand them aside until icy cold; when ready to serve, have at hand a pan of boiling water, hold the mould an instant in this, then turn out in a dish.', 'This is enough for 20 people.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-12-olney-pudding', 'Olney Pudding', 'American', ["month-may", "day-12"], 'eggs', 'dessert', 45, 'Two eggs, 4 ozs. butter, 4 ozs. flour, 2 ozs. sugar, 1/4 teaspoonful carbonate soda, 2 teaspoonfuls ex. of lemon and 2 large spoonfuls of marmalade or any other jam or jelly.', [I('eggs', 2, '', 'Dairy & Eggs'), I('butter', 4, 'ozs', 'Dairy & Eggs'), I('flour', 4, 'ozs', 'Pantry'), I('sugar', 2, 'ozs', 'Pantry'), I('carbonate soda', 0.25, 'teaspoonful', 'Pantry'), I('extract of lemon', 2, 'teaspoonfuls', 'Herbs & Spices'), I('marmalade or any other jam or jelly', 2, 'large spoonfuls', 'Pantry'), I('cold water', 1, 'teaspoonful', 'Pantry')], ['Two eggs, 4 ozs. butter, 4 ozs. flour, 2 ozs. sugar, 1/4 teaspoonful carbonate soda, 2 teaspoonfuls ex. of lemon and 2 large spoonfuls of marmalade or any other jam or jelly.', 'Stand 2 hours in a buttered mould; put the batter into a basin and stir to a cream, add the sugar, mix them together with the flour and add the eggs well beaten; dissolve the soda in a teaspoonful of cold water, mix well in the jam or jelly and add soda.', 'Serve with sweet sauce or a spoonful of the jam can be mixed with the sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-13-fig-mould', 'Fig Mould', 'American', ["month-may", "day-13"], 'veg', 'dessert', 45, 'Two pounds of figs, 1 large cup of sugar, 1 1/2 pints of water, 1/2 small box of gelatine, 1 coffee cup of sherry.', [I('figs', 2, 'pounds', 'Produce'), I('sugar', 1, 'large cup', 'Pantry'), I('water', 1.5, 'pints', 'Pantry'), I('gelatine', 0.5, 'small box', 'Pantry'), I('sherry', 1, 'coffee cup', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs')], ['Two pounds of figs, 1 large cup of sugar, 1 1/2 pints of water, 1/2 small box of gelatine, 1 coffee cup of sherry.', 'Stew the figs and sugar in the water for one hour, add the gelatine and sherry, pour into a mould.', 'Should be eaten cold with cream, plain or whipped.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-14-lemon-cream', 'Lemon Cream', 'American', ["month-may", "day-14"], 'veg', 'dessert', 45, 'Beat 1 1/2 pints of cream to a stiff froth; sweeten to taste with fine sugar; squeeze in the juice of 4 lemons; add 1 tablespoonful of gelatine soaked in cold water and dissolved in a little hot water.', [I('cream', 1.5, 'pints', 'Dairy & Eggs'), I('sugar (to taste)', 1, '', 'Pantry'), I('lemons', 4, '', 'Produce'), I('gelatine soaked', 1, 'tablespoonful', 'Pantry'), I('water', 1, '', 'Pantry')], ['Beat 1 1/2 pints of cream to a stiff froth; sweeten to taste with fine sugar; squeeze in the juice of 4 lemons; add 1 tablespoonful of gelatine soaked in cold water and dissolved in a little hot water.', 'Pour it into a greased mould.', 'It is better to make it the day before it is required.—From Good Housekeeping.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-15-swiss-tart', 'Swiss Tart', 'American', ["month-may", "day-15"], 'eggs', 'dessert', 45, 'Make a short paste as follows: Take 1 lb. of pastry flour, rub in 10 ozs. of butter, 2 ozs. of fine sugar and nearly 1/2 pint of milk ; mix this to a moderately stiff paste, then roll out, give it 2 turns, as we term it in pastry making ; then roll out about 1/2 inch in thickness, cut out pieces the size of a cheese plate, place these on a baking tin, egg around the edge and surround with a border of paste; place some raspberry jam in each “shell” and bake.', [I('pastry flour', 1, 'lb', 'Pantry'), I('butter', 10, 'ozs', 'Dairy & Eggs'), I('fine sugar', 2, 'ozs', 'Pantry'), I('milk (nearly 1/2 pint)', 1, '', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('raspberry jam', 1, '', 'Produce'), I('meringue mixture', 1, '', 'Pantry'), I('pink sugar (a little)', 1, '', 'Pantry')], ['Make a short paste as follows: Take 1 lb. of pastry flour, rub in 10 ozs. of butter, 2 ozs. of fine sugar and nearly 1/2 pint of milk ; mix this to a moderately stiff paste, then roll out, give it 2 turns, as we term it in pastry making ; then roll out about 1/2 inch in thickness, cut out pieces the size of a cheese plate, place these on a baking tin, egg around the edge and surround with a border of paste; place some raspberry jam in each “shell” and bake.', 'Make a meringue mixture and spread some over the tarts, then take some of the mixture in a bag and with a tube make the form of a star or any other design for the centre.', 'Place a border around the edge, sprinkle a little pink sugar over, bake in a moderately cool oven a golden brown.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-16-batter-pudding-with-strawberries', 'Batter Pudding with Strawberries', 'American', ["month-may", "day-16"], 'eggs', 'dessert', 45, 'One pint of milk, one tablespoonful of melted butter, three and one-half cups of flour, three eggs, two heaping teaspoonfuls of baking powder, one-half teaspoonful of salt, one pint of strawberries.', [I('milk', 1, 'pint', 'Dairy & Eggs'), I('melted butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('flour', 3.5, 'cups', 'Pantry'), I('eggs', 3, '', 'Dairy & Eggs'), I('baking powder', 2, 'heaping teaspoonfuls', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('strawberries', 1, 'pint', 'Produce'), I('flour', 1, '', 'Pantry')], ['One pint of milk, one tablespoonful of melted butter, three and one-half cups of flour, three eggs, two heaping teaspoonfuls of baking powder, one-half teaspoonful of salt, one pint of strawberries.', 'Beat the eggs, whites and yolks together until light, then add the milk, then the flour, and heat until smooth, then add the butter melted, salt and baking powder.', 'Dredge the berries with flour, stir them into the pudding, and turn into a greased pudding mould.', 'Cover, stand in a pot of boiling water and boil continuously for three hours.', 'If the water evaporates in the pot, replenish with boiling water.', 'Serve with hard sauce flavored with sherry.—From “Table Talk.”'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-17-brazilian-pudding', 'Brazilian Pudding', 'American', ["month-may", "day-17"], 'eggs', 'dessert', 45, 'Put 2 cups of stale bread crumbs into 1 qt. of milk; beat with a No. 1 Keystone beater, the yolks of 4 eggs and 1/2 cup of sugar until very light, then beat the whites until stiff and dry.', [I('stale bread crumbs', 2, 'cups', 'Pantry'), I('milk', 1, 'qt', 'Dairy & Eggs'), I('eggs', 4, '', 'Dairy & Eggs'), I('sugar', 0.5, 'cup', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs'), I('raisins', 1, '', 'Produce')], ['Put 2 cups of stale bread crumbs into 1 qt. of milk; beat with a No. 1 Keystone beater, the yolks of 4 eggs and 1/2 cup of sugar until very light, then beat the whites until stiff and dry.', 'Now add the yolks and sugar to the bread and milk and then stir in the whites.', 'Butter a pudding mould, spread the bottom with raisins, pour in the mixture and bake in a moderate oven 1 1/2 hours.', 'Serve cold.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-18-cocoanut-tarts', 'Cocoanut Tarts', 'American', ["month-may", "day-18"], 'eggs', 'dessert', 45, 'Put 1/2 lb. of sugar and 1 gill of water in a sauce pan, stir over the fire until the sugar is dissolved, then boil hard just one minute ; add 1 cup of grated cocoanut and boil 2 minutes longer.', [I('sugar', 0.5, 'lb', 'Pantry'), I('water', 1, 'gill', 'Pantry'), I('grated cocoanut', 1, 'cup', 'Produce'), I('eggs', 3, '', 'Dairy & Eggs'), I('light paste', 1, '', 'Pantry'), I('eggs', 2, '', 'Dairy & Eggs'), I('powdered sugar', 2, 'tablespoonfuls', 'Pantry')], ['Put 1/2 lb. of sugar and 1 gill of water in a sauce pan, stir over the fire until the sugar is dissolved, then boil hard just one minute ; add 1 cup of grated cocoanut and boil 2 minutes longer.', 'Stand away to cool, beat the yolks of 3 eggs and the white of one to a very light cream, add this to the cocoanut when cold and beat until light.', 'If properly beaten it will look like a sponge cake batter.', 'Have ready pie tins lined with a nice light paste; fill with this mixture and bake in a quick oven 25 minutes.', 'Beat the whites of 2 eggs until light, add 2 tablespoonfuls of powdered sugar; mix and heap over the top of the tarts, return to the oven a moment to brown.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-19-vanilla-parfait', 'Vanilla Parfait', 'American', ["month-may", "day-19"], 'veg', 'dessert', 45, 'Whip 1 1/2 pts. of cream until light and dry.', [I('cream', 1.5, 'pts', 'Dairy & Eggs'), I('powdered sugar', 0.75, 'cup', 'Pantry'), I('vanilla', 1, 'dessertspoonful', 'Herbs & Spices'), I('suet', 1, '', 'Meat & Seafood'), I('salt', 1, '', 'Herbs & Spices')], ['Whip 1 1/2 pts. of cream until light and dry.', 'After all the cream is nicely whipped add 3/4 of a cup of powdered sugar and a dessertspoonful of vanilla, mix carefully and pour into a mould that has a tight-fitting cover.', 'Put on the lid and bind the crevice with a strip of muslin dipped in suet ; pack the moulds in salt and ice, cover and stand away for 2 hours to quietly freeze.', 'This is especially nice with frozen fruits.—“Table Talk.”'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-20-strawberry-water-ice', 'Strawberry Water Ice', 'American', ["month-may", "day-20"], 'veg', 'dessert', 45, 'One qt. of strawberry juice, the juice of 2 lemons, 1 lb. of sugar and 1 pt. of water; mix well and stand aside for 1 hour and then freeze it.—“Table Talk,” Phila.', [I('strawberry juice', 1, 'qt', 'Produce'), I('lemons', 2, '', 'Produce'), I('sugar', 1, 'lb', 'Pantry'), I('water', 1, 'pt', 'Pantry')], ['One qt. of strawberry juice, the juice of 2 lemons, 1 lb. of sugar and 1 pt. of water; mix well and stand aside for 1 hour and then freeze it.—“Table Talk,” Phila.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-21-cerealine-blocks-with-jelly', 'Cerealine Blocks With Jelly', 'American', ["month-may", "day-21"], 'eggs', 'dessert', 45, 'Put 1 pint of cream in a double boiler, add sufficient cerealine, about 1 1/2 cups, to make a thick batter; add a teaspoonful of salt and beat until smooth and light, turn into a square tin mould to cool; when cold, turn out and cut into blocks.', [I('cream', 1, 'pint', 'Dairy & Eggs'), I('cerealine (sufficient, about 1 1/2 cups)', 1, '', 'Pantry'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('fat', 1, '', 'Pantry'), I('powdered sugar', 1, '', 'Pantry'), I('currant jelly', 0.5, 'tumbler', 'Produce'), I('egg', 1, '', 'Dairy & Eggs')], ['Put 1 pint of cream in a double boiler, add sufficient cerealine, about 1 1/2 cups, to make a thick batter; add a teaspoonful of salt and beat until smooth and light, turn into a square tin mould to cool; when cold, turn out and cut into blocks.', 'Drop quickly into smoking hot fat and cook until a golden brown.', 'Drain on soft brown paper; dust with powdered sugar and serve with the following: CuRRANT JELLY Sauce.—Put 1/2 tumbler of currant jelly into a bowl and beat until it is thoroughly aerated; then mix in carefully the well-beaten white of one egg; stand in a cold place until wanted.—“Table Talk.”'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-22-delmonico-pudding', 'Delmonico Pudding', 'American', ["month-may", "day-22"], 'eggs', 'dessert', 45, 'Three pints milk, 3 eggs, 4 1/2 heaping spoonfuls corn meal, 1 cup sugar.', [I('milk', 3, 'pints', 'Dairy & Eggs'), I('eggs', 3, '', 'Dairy & Eggs'), I('corn meal', 4.5, 'heaping spoonfuls', 'Produce'), I('sugar', 1, 'cup', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs')], ['Three pints milk, 3 eggs, 4 1/2 heaping spoonfuls corn meal, 1 cup sugar.', 'Pour the boiling milk on to the beaten yolks of the eggs, add the meal and the sugar, beat all together.', 'Cook for 5 minutes, stirring constantly.', 'Remove from the fire and add the whites beaten stiff.', 'Pour into a pudding-dish and bake about an hour in a moderate oven.', 'Serve with hard sauce or cream and sugar.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-23-irish-moss-blanc-mange', 'Irish Moss Blanc Mange', 'American', ["month-may", "day-23"], 'veg', 'dessert', 45, 'Wash 1/2 ounce Irish moss through several cold waters, then soak it 1 hour in 1 quart milk, turn it into a farina boiler, and cook slowly, until the moss is almost dissolved.', [I('Irish moss', 0.5, 'ounce', 'Pantry'), I('milk', 1, 'quart', 'Dairy & Eggs'), I('sugar', 0.5, 'cup', 'Pantry'), I('wine', 1, '', 'Pantry'), I('sherry', 1, '', 'Pantry')], ['Wash 1/2 ounce Irish moss through several cold waters, then soak it 1 hour in 1 quart milk, turn it into a farina boiler, and cook slowly, until the moss is almost dissolved.', 'Add 1/2 cup sugar and the flavoring.', 'Strain and turn into a mould, and stand in a very cold place to stiffen.', 'If you use wine, sherry would be the better flavoring.—“Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-24-royal-fritters', 'Royal Fritters', 'American', ["month-may", "day-24"], 'eggs', 'dessert', 45, 'Put 1 pt. of milk in a farina boiler to heat ; when hot, add the juice of 1 lemon; take from the fire, let it stand 5 or 6 minutes for the curd to settle.', [I('milk', 1, 'pt', 'Dairy & Eggs'), I('lemon (juice)', 1, '', 'Produce'), I('eggs', 3, '', 'Dairy & Eggs'), I('nutmeg', 0.25, '', 'Herbs & Spices'), I('powdered sugar', 2, 'tablespoonfuls', 'Pantry'), I('flour (sufficient, about 1/2 cup)', 1, '', 'Pantry'), I('lard', 1, '', 'Meat & Seafood'), I('powdered sugar', 1, '', 'Pantry')], ['Put 1 pt. of milk in a farina boiler to heat ; when hot, add the juice of 1 lemon; take from the fire, let it stand 5 or 6 minutes for the curd to settle.', 'Beat 3 eggs until very light, drain the curd from the milk and add it to the eggs; add 1/4 of a nutmeg, 2 tablespoonfuls of powdered sugar and sufficient flour, about 1/2 cup to form a smooth batter.', 'Now beat until smooth and light.', 'Have ready a deep pan of hot lard; drop the batter by spoonfuls into it and fry quickly a light brown.', 'When done, place on a sieve to drain.', 'Serve hot, dusted with powdered sugar.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-25-mrs-b-s-puffies', 'Mrs. B.’s Puffies', 'American', ["month-may", "day-25"], 'eggs', 'dessert', 45, 'One quart of milk and water, 2 parts milk and 1 of water, 2 eggs, a little salt, flour enough to make a soft batter; heat the pans, and pour the mixture in; bake until a light brown.', [I('milk and water', 1, 'quart', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('salt (a little)', 1, '', 'Herbs & Spices'), I('flour', 1, '', 'Pantry')], ['One quart of milk and water, 2 parts milk and 1 of water, 2 eggs, a little salt, flour enough to make a soft batter; heat the pans, and pour the mixture in; bake until a light brown.', 'Serve with sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-26-ginger-sherbet', 'Ginger Sherbet', 'American', ["month-may", "day-26"], 'veg', 'dessert', 45, 'Put 2 lbs. of sugar and 2 quarts of water on to boil, stir until the sugar is dissolved, then boil rapidly for 5 minutes, take from the fire and stand aside to cool.', [I('sugar', 2, 'lbs', 'Pantry'), I('water', 2, 'quarts', 'Pantry'), I('lemons (juice)', 6, '', 'Produce'), I('orange (juice)', 1, '', 'Produce'), I('preserved ginger', 5, 'ozs', 'Herbs & Spices'), I('preserved ginger (in very thin slices)', 1, 'oz', 'Herbs & Spices')], ['Put 2 lbs. of sugar and 2 quarts of water on to boil, stir until the sugar is dissolved, then boil rapidly for 5 minutes, take from the fire and stand aside to cool.', 'When cold, add the juice of 6 nice lemons and 1 orange ; pour into the freezer and freeze without much turning.', 'When frozen add 5 ozs. of preserved ginger chopped fine, then pounded to a paste; cut 1 oz. in very thin slices and add it also.', 'Cover the freezing can and stand away for 2 hours to harden and ripen.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-27-beignet-souffle', 'Beignet Souffle', 'American', ["month-may", "day-27"], 'eggs', 'dessert', 45, 'Put 1 pt. of milk in a sauce pan with a few grains of salt, a piece of butter the size of an egg, 2 ozs. of sugar, some grated lemon peel and 3 ozs. of flour, wet with a little of the milk when cold, and stirred in when it boils to form a thick paste.', [I('milk', 1, 'pt', 'Dairy & Eggs'), I('a few grains of salt', 1, '', 'Herbs & Spices'), I('butter (the size of an egg)', 1, '', 'Dairy & Eggs'), I('sugar', 2, 'ozs', 'Pantry'), I('grated lemon peel', 1, '', 'Produce'), I('flour', 3, 'ozs', 'Pantry'), I('eggs', 2, '', 'Dairy & Eggs'), I('lard', 1, '', 'Meat & Seafood'), I('powdered sugar', 1, '', 'Pantry'), I('sliced lemon', 1, '', 'Produce')], ['Put 1 pt. of milk in a sauce pan with a few grains of salt, a piece of butter the size of an egg, 2 ozs. of sugar, some grated lemon peel and 3 ozs. of flour, wet with a little of the milk when cold, and stirred in when it boils to form a thick paste.', 'Then add the lightly beaten yolks and whites of 2 eggs.', 'Let it stand 2 or 3 hours and then fry in pieces the size of a walnut dropped into hot lard.', 'Serve with powdered sugar over and sliced lemon.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-28-prune-pie', 'Prune Pie', 'American', ["month-may", "day-28"], 'veg', 'dessert', 45, 'Cover the desired amount of prunes with water and soak over night; in the morning drain, have a dish lined with pie crust, fill with the prunes, sprinkle over 4 tablespoons of sugar and 1 tablespoonful of lemon juice, cover with an upper crust and bake in a moderately quick oven for 30 minutes.', [I('prunes', 1, '', 'Produce'), I('water', 1, '', 'Pantry'), I('pie crust', 1, '', 'Pantry'), I('sugar', 4, 'tablespoons', 'Pantry'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('upper crust', 1, '', 'Pantry')], ['Cover the desired amount of prunes with water and soak over night; in the morning drain, have a dish lined with pie crust, fill with the prunes, sprinkle over 4 tablespoons of sugar and 1 tablespoonful of lemon juice, cover with an upper crust and bake in a moderately quick oven for 30 minutes.', 'The moisture of the prunes should blend with the sugar and form a syrup.', 'If the prunes are hard they may require a little cooking before going into the pie, but if they are soft, the pie will be richer if put at once into crust.', 'The lemon juice must be added or the pie will be flat.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-29-meringues', 'Meringues', 'American', ["month-may", "day-29"], 'eggs', 'dessert', 45, 'Beat the whites of four eggs to a very stiff froth; stir in carefully eight ounces of powdered sugar, one teaspoonful of vanilla sugar, and put them at once on greased paper, this on a heavy board or plank, then into a moderate oven where they will simply dry. if the oven is hot, they will swell, crust on the outside, then fall, and you have a result very much like the meringue on the top of a pie.', [I('eggs', 4, '', 'Dairy & Eggs'), I('powdered sugar', 8, 'ounces', 'Pantry'), I('vanilla sugar', 1, 'teaspoonful', 'Herbs & Spices')], ['Beat the whites of four eggs to a very stiff froth; stir in carefully eight ounces of powdered sugar, one teaspoonful of vanilla sugar, and put them at once on greased paper, this on a heavy board or plank, then into a moderate oven where they will simply dry. if the oven is hot, they will swell, crust on the outside, then fall, and you have a result very much like the meringue on the top of a pie.', 'It is wise to have the paper greased, fitted on the board, and the oven in good condition before beginning to beat the whites of the eggs.', 'After the sugar is added, the mixing must be most carefully done or the sugar will melt, making the whites of the eggs liquid, and of course they will not keep their shape.', 'Kisses may be made with the pastry-bag or in round shapes with a teaspoon.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-30-strawberry-charlottes', 'Strawberry Charlottes', 'American', ["month-may", "day-30"], 'veg', 'dessert', 45, 'Cover one-fourth of a box of gelatine with a quarter of a cup of cold water, whip one pint of cream until it makes three pints.', [I('gelatine', 0.25, 'box', 'Pantry'), I('cold water', 0.25, 'cup', 'Pantry'), I('cream', 1, 'pint', 'Dairy & Eggs'), I('granulated sugar', 0.3333, 'cup', 'Pantry'), I('milk (if no cream is left over)', 1, 'small cup full', 'Dairy & Eggs'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('whole strawberries', 1, '', 'Produce')], ['Cover one-fourth of a box of gelatine with a quarter of a cup of cold water, whip one pint of cream until it makes three pints.', 'If any is left boil it with one-third of a cup of granulated sugar (if no cream is left over a small cup full of milk); when boiling add the gelatine and stir until dissolved.', 'Strain it into a bowl and add a tablespoonful of lemon juice.', 'Stand the bowl in a pan of crushed ice, stir occasionally, and when the mixture is cold and begins to thicken, stir in lightly the whipped cream.', 'Line a mould with whole strawberries, and when the cream is nearly stiff enough to dry pour it into the mould.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-may-31-italian-cream', 'Italian Cream', 'American', ["month-may", "day-31"], 'veg', 'dessert', 45, 'One quart whipped cream; the juice of 2 lemons into 2 wine-glasses of wine; 6 ounces of sugar.', [I('whipped cream', 1, 'quart', 'Dairy & Eggs'), I('lemons', 2, '', 'Produce'), I('wine', 2, 'wine-glasses', 'Pantry'), I('sugar', 6, 'ounces', 'Pantry'), I('gelatine', 2, 'ounces', 'Pantry'), I('water (a small quantity)', 1, '', 'Pantry')], ['One quart whipped cream; the juice of 2 lemons into 2 wine-glasses of wine; 6 ounces of sugar.', 'Dissolve 2 ounces of gelatine in a small quantity of water; let this boil together once, and when milk-warm add the cream, and pour into moulds.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-01-cherry-bread-pudding', 'Cherry Bread Pudding', 'American', ["month-june", "day-01"], 'eggs', 'dessert', 45, 'One qt. of milk, with a pinch of soda stirred in, slices of bread and butter, 4 eggs or 2 for a plain pudding, 1 teacup of sugar, 1 teacup stoned cherries.', [I('milk', 1, 'qt', 'Dairy & Eggs'), I('soda', 1, 'pinch', 'Pantry'), I('bread and butter', 1, '', 'Dairy & Eggs'), I('4 eggs or 2 for a plain pudding', 1, '', 'Dairy & Eggs'), I('sugar', 1, 'teacup', 'Pantry'), I('stoned cherries', 1, 'teacup', 'Produce')], ['One qt. of milk, with a pinch of soda stirred in, slices of bread and butter, 4 eggs or 2 for a plain pudding, 1 teacup of sugar, 1 teacup stoned cherries.', 'Put a layer of bread and butter in the bottom of a pie dish, and pour upon it a little warm custard made of the beaten eggs, sugar and milk ; put over this a layer of cherries, then more bread and butter and custard, and proceed in this order till the dish is full, taking care that the top is bread well buttered.', 'Cover with a dish, and let it soak for an hour ; then put it still covered in a pan of hot water, and bake for 1 hour; then uncover and brown delicately.', 'Serve hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-02-strawberry-shortcake', 'Strawberry Shortcake', 'American', ["month-june", "day-02"], 'eggs', 'dessert', 45, 'Sift together 1 qt. of flour, 2 heaping teaspoonfuls of baking powder, 2 tablespoonfuls of powdered sugar and 1 teaspoonful of salt.', [I('flour', 1, 'qt', 'Pantry'), I('baking powder', 2, 'heaping teaspoonfuls', 'Pantry'), I('powdered sugar', 2, 'tablespoonfuls', 'Pantry'), I('salt', 1, 'teaspoonful', 'Herbs & Spices'), I('butter', 3, 'ozs', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('sweet unskimmed milk', 0.5, 'pt', 'Dairy & Eggs'), I('strawberries', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs')], ['Sift together 1 qt. of flour, 2 heaping teaspoonfuls of baking powder, 2 tablespoonfuls of powdered sugar and 1 teaspoonful of salt.', 'Chop up 3 ozs. of butter in this prepared flour.', 'Beat one egg in a bowl, add to it a half pt. of sweet unskimmed milk, and mix well.', 'Pour this quickly, but a little at a time, into the flour, stirring until thoroughly mixed.', 'Roll out about 1 1/2 inches thick and bake in a large well greased square baking pan, about 20 minutes in a very hot oven.', 'When done split in halves and butter both halves.', 'Place one on a large dish and dust it with powdered sugar.', 'Cover it well with strawberries slightly mashed, sprinkle thickly with powdered sugar.', 'Place the other half, crust side down on top of the berries, and cover with fruit and sugar as before.', 'Serve hot with cream.—“Table Talk.”'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-03-fruit-jelly', 'Fruit Jelly', 'American', ["month-june", "day-03"], 'veg', 'dessert', 45, 'Three-fourths of a box of gelatine dissolved in 1/2 pint of cold water.', [I('gelatine dissolved', 0.75, 'box', 'Pantry'), I('cold water', 0.5, 'pint', 'Pantry'), I('boiling water', 1, 'pint', 'Pantry'), I('lemons', 2, '', 'Produce'), I('sugar', 2, 'cups', 'Pantry'), I('wine', 1, 'cup', 'Pantry'), I('oranges', 2, '', 'Produce'), I('bananas', 2, '', 'Produce'), I('figs', 6, '', 'Produce'), I('dates', 9, '', 'Produce'), I('10 English walnuts', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs')], ['Three-fourths of a box of gelatine dissolved in 1/2 pint of cold water.', 'Then add one pint of boiling water, juice of 2 lemons, 2 cups of sugar, 1 cup of wine; strain, and when beginning to harden, stir in the following fruits cut up in pieces, two oranges, 2 bananas, 6 figs, 9 dates, 10 English walnuts.', 'Pour in a border mould.', 'Serve ice-cold with whipped cream that has been sweetened and flavored piled high in the centre..'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-04-strawberry-pie', 'Strawberry Pie', 'American', ["month-june", "day-04"], 'veg', 'dessert', 45, 'This is very nice, made like any other fruit pie, but it is nicer if the berries are slightly mashed, sprinkled with powdered sugar and heaped in shells of paste which have been previously baked.', [I('berries', 1, '', 'Produce'), I('powdered sugar', 1, '', 'Pantry'), I('shells of paste', 1, '', 'Pantry'), I('whipped cream', 1, '', 'Dairy & Eggs')], ['This is very nice, made like any other fruit pie, but it is nicer if the berries are slightly mashed, sprinkled with powdered sugar and heaped in shells of paste which have been previously baked.', 'Pile whipped cream on top.—“Table Talk,” Phila.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-05-cerealine-fritters-with-apples', 'Cerealine Fritters with Apples', 'American', ["month-june", "day-05"], 'eggs', 'dessert', 45, 'Put 1 pt. of milk on to heat in a double boiler ; when hot, stir in 1/2 lb. cerealine ; cook 5 minutes, add 1/2 teaspoonful salt, 3 tablespoonfuls sugar, grated rind of 1/2 lemon, and 1/4 teaspoonful mace.', [I('milk', 1, 'pt', 'Dairy & Eggs'), I('cerealine', 0.5, 'lb', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('sugar', 3, 'tablespoonfuls', 'Pantry'), I('lemon (grated rind)', 0.5, '', 'Produce'), I('mace', 0.25, 'teaspoonful', 'Herbs & Spices'), I('good-sized tart apples', 3, '', 'Produce'), I('egg', 1, '', 'Dairy & Eggs'), I('milk', 1, '', 'Dairy & Eggs'), I('flour', 1, '', 'Pantry'), I('fat', 1, '', 'Pantry'), I('powdered sugar', 1, '', 'Pantry')], ['Put 1 pt. of milk on to heat in a double boiler ; when hot, stir in 1/2 lb. cerealine ; cook 5 minutes, add 1/2 teaspoonful salt, 3 tablespoonfuls sugar, grated rind of 1/2 lemon, and 1/4 teaspoonful mace.', 'Pare, core and quarter 3 good-sized tart apples, put into glass and with No. 1 keystone egg-beater, first cut the apples by giving a backward and forward motion ; then turn slowly and regularly until the apples are reduced to a pulp; add this to the hot cerealine mixture and turn into a square greased mould to cool.', 'When cold, cut into blocks, dip in a thin batter made from egg, milk and flour, and fry in hot fat.', 'Serve hot with powdered sugar sifted over them.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-06-iced-cocoa', 'Iced Cocoa', 'American', ["month-june", "day-06"], 'veg', 'dessert', 45, 'To a pt. of cocoa, made in the usual way, add 1/2 of a cup of whipped cream.', [I('cocoa', 1, 'pt', 'Pantry'), I('whipped cream', 0.5, 'cup', 'Dairy & Eggs'), I('sugar (to taste)', 1, '', 'Pantry')], ['To a pt. of cocoa, made in the usual way, add 1/2 of a cup of whipped cream.', 'Beat it into the cocoa, sweeten to taste and stand until cool.', 'Serve in glasses partly filled with chipped ice.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-07-strawberry-sponge-cake', 'Strawberry Sponge Cake', 'American', ["month-june", "day-07"], 'eggs', 'dessert', 45, 'Make an ordinary sponge cake from 6 eggs, bake it in a long baking tin ; when done, cut into halves, upon 1/2 put a thick meringue, made from the whites of 2 eggs, and 2 tablespoonfuls of powdered sugar, beat the eggs until light, add the sugar, and beat until white.', [I('ordinary sponge cake', 1, '', 'Pantry'), I('eggs', 6, '', 'Dairy & Eggs'), I('eggs', 2, '', 'Dairy & Eggs'), I('powdered sugar', 2, 'tablespoonfuls', 'Pantry'), I('strawberries', 1, '', 'Produce'), I('cream', 1, '', 'Dairy & Eggs')], ['Make an ordinary sponge cake from 6 eggs, bake it in a long baking tin ; when done, cut into halves, upon 1/2 put a thick meringue, made from the whites of 2 eggs, and 2 tablespoonfuls of powdered sugar, beat the eggs until light, add the sugar, and beat until white.', 'Stand large strawberries thickly over this; put on the upper half, cover with strawberries neatly arranged, dust with sugar and serve with cream.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-08-pineapple-jelly', 'Pineapple Jelly', 'American', ["month-june", "day-08"], 'veg', 'dessert', 45, 'Cover one box of gelatine with a half pint of cold water, and soak it half an hour.', [I('gelatine', 1, 'box', 'Pantry'), I('cold water', 0.5, 'pint', 'Pantry'), I('medium-sized pineapples', 2, '', 'Produce'), I('pulp', 1.5, 'pounds', 'Pantry'), I('sugar', 1, 'lb', 'Pantry'), I('lemon juice', 1, 'tablespoonful', 'Produce'), I('boiling water', 0.5, 'pint', 'Pantry'), I('water', 1, 'quart', 'Pantry')], ['Cover one box of gelatine with a half pint of cold water, and soak it half an hour.', 'While this is soaking pare and grate two medium-sized pineapples.', 'After the pineapples are grated you should have one and one-half pounds of pulp.', 'Add to this, 1 lb. of sugar and a tablespoonful of lemon juice ; stir until the sugar is dissolved.', 'Add to the gelatine a half pint of boiling water.', 'Strain this into the pineapple; mix thoroughly; turn in a mould and stand away to harden.', 'Another method is to boil the pineapple, the same amount given above, in one quart of water.', 'The water is then strained and the gelatine added to it. 1 lb. of sugar is then stirred in, and the mixture turned into the mould to harden.—“Table Talk.”'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-09-strawberry-bavarian-cream', 'Strawberry Bavarian Cream', 'American', ["month-june", "day-09"], 'veg', 'dessert', 45, 'Mash sufficient strawberries to make one pint of strained juice.', [I('strawberries', 1, '', 'Produce'), I('strained juice', 1, 'pint', 'Pantry'), I('gelatine', 0.5, 'box', 'Pantry'), I('cold water', 0.5, 'cup', 'Pantry'), I('powdered sugar', 1, 'cup', 'Pantry'), I('cream', 1, 'pint', 'Dairy & Eggs'), I('milk', 1, 'gill', 'Dairy & Eggs')], ['Mash sufficient strawberries to make one pint of strained juice.', 'Cover one-half a box of gelatine with one-half cup of cold water and let it stand for half an hour; add to the strawberry juice one cup of powdered sugar, stir until dissolved ; whip one pint of cream, put the juice in a pan, stand it in another of cracked ice.', 'Now add a gill of milk to the gelatine and stand it over boiling water until thoroughly melted, strain this into the strawberry juice, then add the whipped cream and stir carefully until well blended and partly congealed.', 'If you do not stir until the mass begins to thicken the gelatine will settle to the bottom.', 'You should have a perfectly light charlotte.', 'Turn this into a greased mould and stand away to harden.', 'Serve with whipped cream around the base, or you may serve it with a garnish of fresh strawberries.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-10-currant-fritters', 'Currant Fritters', 'American', ["month-june", "day-10"], 'eggs', 'dessert', 45, 'One pt. of milk, 2 teacupfuls of flour, 1/2 teacupful of currants, 3 eggs beaten stiff, 2 teaspoonfuls of baking powder, 1/2 of a teaspoonful of salt, 2 tablespoonfuls of sugar.', [I('milk', 1, 'pt', 'Dairy & Eggs'), I('flour', 2, 'teacupfuls', 'Pantry'), I('currants', 0.5, 'teacupful', 'Produce'), I('eggs', 3, '', 'Dairy & Eggs'), I('baking powder', 2, 'teaspoonfuls', 'Pantry'), I('salt', 0.5, 'teaspoonful', 'Herbs & Spices'), I('sugar', 2, 'tablespoonfuls', 'Pantry'), I('lard', 1, '', 'Meat & Seafood')], ['One pt. of milk, 2 teacupfuls of flour, 1/2 teacupful of currants, 3 eggs beaten stiff, 2 teaspoonfuls of baking powder, 1/2 of a teaspoonful of salt, 2 tablespoonfuls of sugar.', 'Drop in hot lard and serve with wine sauce.—From Good Housekeeping.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-11-turkish-sherbet', 'Turkish Sherbet', 'American', ["month-june", "day-11"], 'veg', 'dessert', 45, 'Boil 2 cups of granulated sugar with 3/4 of a pt. of water to a clear syrup; skim carefully, and when cold stir into it 3/4 of a pt. of strained lemon juice and one cup of clear white stock.—From “Table Talk,” Philadelphia.', [I('granulated sugar', 2, 'cups', 'Pantry'), I('water', 0.75, 'pt', 'Pantry'), I('strained lemon juice', 0.75, 'pt', 'Produce'), I('clear white stock', 1, 'cup', 'Dairy & Eggs')], ['Boil 2 cups of granulated sugar with 3/4 of a pt. of water to a clear syrup; skim carefully, and when cold stir into it 3/4 of a pt. of strained lemon juice and one cup of clear white stock.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-12-jaune-mange', 'Jaune Mange', 'American', ["month-june", "day-12"], 'eggs', 'dessert', 45, 'Put into a pint of water the thin rind of a lemon and 3/4 lb. of sugar; put it on the fire and allow it to simmer for 3 or 4 minutes, stirring all the time; add an oz. and a half of gelatine, and stir till dissolved ; then the juice of a lemon, a pint of sherry and the yolks of 8 eggs.', [I('water', 1, 'pint', 'Pantry'), I('lemon (thin rind)', 1, '', 'Produce'), I('sugar', 0.75, 'lb', 'Pantry'), I('gelatine', 1.5, 'oz', 'Pantry'), I('lemon (juice)', 1, '', 'Produce'), I('sherry', 1, 'pint', 'Pantry'), I('eggs', 8, '', 'Dairy & Eggs')], ['Put into a pint of water the thin rind of a lemon and 3/4 lb. of sugar; put it on the fire and allow it to simmer for 3 or 4 minutes, stirring all the time; add an oz. and a half of gelatine, and stir till dissolved ; then the juice of a lemon, a pint of sherry and the yolks of 8 eggs.', 'Strain and put into moulds.', 'Serve cold.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-13-steamed-wheat-pudding', 'Steamed Wheat Pudding', 'American', ["month-june", "day-13"], 'beef', 'dessert', 45, 'One pint of flour, one egg, one cup of milk, one cup of chopped suet, one tablespoonful sugar, two teaspoonfuls of baking powder, and a pinch of salt.', [I('flour', 1, 'pint', 'Pantry'), I('egg', 1, '', 'Dairy & Eggs'), I('milk', 1, 'cup', 'Dairy & Eggs'), I('chopped suet', 1, 'cup', 'Meat & Seafood'), I('sugar', 1, 'tablespoonful', 'Pantry'), I('baking powder', 2, 'teaspoonfuls', 'Pantry'), I('salt', 1, 'pinch', 'Herbs & Spices'), I('sugar', 1, 'cup', 'Pantry'), I('butter', 0.5, 'cup', 'Dairy & Eggs'), I('strawberries thoroughly mashed', 1, 'cup', 'Produce')], ['One pint of flour, one egg, one cup of milk, one cup of chopped suet, one tablespoonful sugar, two teaspoonfuls of baking powder, and a pinch of salt.', 'Steam an hour and a half, and serve with sauce.', 'SAUCE.— One cup of sugar, half cup of butter, the white of an egg beaten stiff, one cup strawberries thoroughly mashed.— Miss L. S.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-14-chess-pie', 'Chess Pie', 'American', ["month-june", "day-14"], 'eggs', 'dessert', 45, 'For 2 pies; 5 eggs, 3/4 of a cup of butter, 1 cupful sugar; flavor to suit.', [I('eggs', 5, '', 'Dairy & Eggs'), I('butter', 0.75, 'cup', 'Dairy & Eggs'), I('sugar', 1, 'cupful', 'Pantry'), I('crust', 1, '', 'Pantry')], ['For 2 pies; 5 eggs, 3/4 of a cup of butter, 1 cupful sugar; flavor to suit.', 'Beat the yolks and sugar together until the froth is perfect.', 'Beat the butter to a creamy froth, flavor and mix quickly.', 'Bake in a crust.', 'It will rise very light.', 'As soon as done have ready a stiff froth made of the whites of the eggs sweetened and flavored.', 'Spread this over the pie and return to the oven to brown a delicate shade.', 'Cut and lay on plates before cooling.', 'This must be done or it will be heavy.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-15-celestine-cream', 'Celestine Cream', 'American', ["month-june", "day-15"], 'veg', 'dessert', 45, 'Imbed a plain mould in some rough ice.', [I('wine', 1, '', 'Pantry'), I('strawberries', 1, 'box', 'Produce'), I('fine sugar', 6, 'ounces', 'Pantry'), I('whipped cream', 1, 'pint', 'Dairy & Eggs'), I('gelatine', 2, 'ounces', 'Pantry')], ['Imbed a plain mould in some rough ice.', 'Line the bottom and sides of the mould with fresh strawberries, taking care to put each one in dissolved gelatine, in which has been mixed some wine to flavor.', 'When the mould is well covered, fill with the following.', 'Pick over a box of strawberries, bruise them with a wooden spoon in a basin, with six ounces of fine sugar, rub this through a hair sieve, add a pint of whipped cream and two ounces of gelatine, which has been dissolved, mix with the strained strawberries and put in the mould.', 'Stand away to harden and serve very cold.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-16-heston-pudding-with-strawberries', 'Heston Pudding with Strawberries', 'American', ["month-june", "day-16"], 'eggs', 'dessert', 45, 'Put one pint of water in a sauce pan.', [I('water', 1, 'pint', 'Pantry'), I('cornstarch', 4, 'even tablespoonfuls', 'Produce'), I('cold water (a little)', 1, '', 'Pantry'), I('sugar', 0.5, 'cup', 'Pantry'), I('berries', 1, 'box', 'Produce'), I('eggs', 3, '', 'Dairy & Eggs'), I('milk', 1, 'pint', 'Dairy & Eggs'), I('sugar', 4, 'tablespoonfuls', 'Pantry')], ['Put one pint of water in a sauce pan.', 'Moisten four even tablespoonfuls of cornstarch in a little cold water.', 'Add it to the boiling water, stir and cook until clear, add a half cup of sugar.', 'Put one box of berries into a dish, dust them with sugar.', 'Beat the whites of three eggs to a stiff froth, stir them into the pudding, pour it over the berries and stand away to cool.', 'Make a soft custard from the yolks of the eggs, a pint of milk. and four tablespoonfuls of sugar.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-17-strawberry-custard', 'Strawberry Custard', 'American', ["month-june", "day-17"], 'eggs', 'dessert', 45, 'Separate four eggs, put one pint of milk into a double boiler, beat the yolks of the eggs and four tablespoonfuls of sugar until light, add them to the milk, stir constantly until the thickness of cream, take from the fire and stand aside to cool; beat the whites of the eggs until stiff, add to them four tablespoonfuls of powdered sugar and beat again until stiff and white.', [I('eggs', 4, '', 'Dairy & Eggs'), I('milk', 1, 'pint', 'Dairy & Eggs'), I('sugar', 4, 'tablespoonfuls', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs'), I('powdered sugar', 4, 'tablespoonfuls', 'Pantry'), I('strawberries', 1, 'pint', 'Produce')], ['Separate four eggs, put one pint of milk into a double boiler, beat the yolks of the eggs and four tablespoonfuls of sugar until light, add them to the milk, stir constantly until the thickness of cream, take from the fire and stand aside to cool; beat the whites of the eggs until stiff, add to them four tablespoonfuls of powdered sugar and beat again until stiff and white.', 'Put about a pint of strawberries into a glass dish, pour over the custard, heap the whites in spoonfuls over the top, dust with sugar, stand in the oven a minute to brown.', 'Serve icy cold.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-18-pineapple-sponge', 'Pineapple Sponge', 'American', ["month-june", "day-18"], 'eggs', 'dessert', 45, 'One small pineapple or a pint and a half can, one small cup of sugar, one-half box of gelatine, one and a half cups of water, and whites of four eggs.', [I('One small pineapple or a pint and a half can', 1, '', 'Produce'), I('sugar', 1, 'small cup', 'Pantry'), I('gelatine', 0.5, 'box', 'Pantry'), I('water', 1.5, 'cups', 'Pantry'), I('eggs', 4, '', 'Dairy & Eggs'), I('soft custard', 1, '', 'Pantry'), I('wine (to flavor)', 1, '', 'Pantry')], ['One small pineapple or a pint and a half can, one small cup of sugar, one-half box of gelatine, one and a half cups of water, and whites of four eggs.', 'Soak the gelatine in a half cup of cold water.', 'Chop the pineapple and put it and the water in a sauce pan with the sugar, and the remaining cup of water.', 'Simmer ten minutes ; add the gelatine; take from the fire and strain.', 'When cool, add the whites of the eggs, and beat until the mixture begins to thicken ; pour into a mould and let it harden.', 'Serve with soft custard flavored with wine.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-19-strawberry-flummery', 'Strawberry Flummery', 'American', ["month-june", "day-19"], 'veg', 'dessert', 45, 'Place one quart of strawberries in a farina boiler, allow them to heat just a little while until the juice flows freely.', [I('strawberries', 1, 'quart', 'Produce'), I('cornstarch', 2, 'tablespoonfuls', 'Produce'), I('cold water', 1, 'gill', 'Pantry'), I('boiling water', 1, 'pint', 'Pantry'), I('sugar', 1, 'cup', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs')], ['Place one quart of strawberries in a farina boiler, allow them to heat just a little while until the juice flows freely.', 'Have ready two tablespoonfuls of cornstarch, moistened in a gill of cold water; add to the berries one pint of boiling water and a cup of sugar; stir in the cornstarch, stir rapidly for a moment and turn into a mould.', 'Serve icy cold with whipped cream.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-20-egg-puffs-with-sauce', 'Egg Puffs with Sauce', 'American', ["month-june", "day-20"], 'eggs', 'dessert', 45, 'Take two eggs, beat well, then add five spoonfuls of flour, one spoonful of butter, and a half cup of milk, beat all together.', [I('eggs', 2, '', 'Dairy & Eggs'), I('flour', 5, 'spoonfuls', 'Pantry'), I('butter', 1, 'spoonful', 'Dairy & Eggs'), I('milk', 0.5, 'cup', 'Dairy & Eggs'), I('salt', 1, 'pinch', 'Herbs & Spices'), I('baking powder', 1, 'teaspoonful', 'Pantry'), I('milk', 1, 'cup', 'Dairy & Eggs'), I('sugar', 0.5, 'cup', 'Pantry'), I('butter', 1, 'tablespoonful', 'Dairy & Eggs'), I('flour', 1, 'teaspoonful', 'Pantry')], ['Take two eggs, beat well, then add five spoonfuls of flour, one spoonful of butter, and a half cup of milk, beat all together.', 'Add a pinch of salt and a teaspoonful of baking powder.', 'Put in a muffin pan and bake in a quick oven.', 'SAUCE.—One cup of milk, half a cup of sugar, a tablespoonful of butter, a teaspoonful of flour.', 'Mix.', 'Place on the range, let it come to a boil and flavor to taste.', 'Serve hot.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-21-punch-a-la-cardinal', 'Punch A’la Cardinal', 'American', ["month-june", "day-21"], 'veg', 'dessert', 45, 'Make a raspberry water ice as follows: Add the juice of one lemon, and one cup of sugar, to a quart of red raspberries mashed, and let stand for thirty minutes.', [I('lemon', 1, '', 'Produce'), I('sugar', 1, 'cup', 'Pantry'), I('red raspberries mashed', 1, 'quart', 'Produce'), I('water', 1, 'pt', 'Pantry'), I('maraschino', 0.25, 'cup', 'Pantry'), I('red curacoa', 0.25, 'cup', 'Pantry')], ['Make a raspberry water ice as follows: Add the juice of one lemon, and one cup of sugar, to a quart of red raspberries mashed, and let stand for thirty minutes.', 'Press through a sieve, add 1 pt. of water, 1/4 of a cup of maraschino, and 1/4 of a cup of red curacoa.', 'Freeze as water ice, and serve in glasses.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-22-vols-au-vent-of-strawberries', 'Vols Au Vent of Strawberries', 'American', ["month-june", "day-22"], 'eggs', 'dessert', 45, 'Make a good-sized vols au vent from puff paste, and when you take it from the pan brush the top with the yolk of egg and cover thickly with granulated sugar, return to the oven until you have a sort of glaze all over the surface.', [I('puff paste', 1, '', 'Pantry'), I('yolk of egg', 1, '', 'Dairy & Eggs'), I('granulated sugar', 1, '', 'Pantry'), I('fresh strawberries', 1, '', 'Produce'), I('whipped cream', 1, '', 'Dairy & Eggs')], ['Make a good-sized vols au vent from puff paste, and when you take it from the pan brush the top with the yolk of egg and cover thickly with granulated sugar, return to the oven until you have a sort of glaze all over the surface.', 'When you are ready to serve, fill with fresh strawberries.', 'Heap the top with whipped cream and dot with perfect berries and serve.—From “Table Talk,” Phila.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-23-bonny-clabber', 'Bonny Clabber', 'American', ["month-june", "day-23"], 'veg', 'dessert', 45, 'When the milk turns, that is, becomes sour, smooth and thick, put it carefully into a glass dish, stand away to get very cold, dust heavily with powdered sugar, then sprinkle slightly with nutmeg and serve with sweetened cream.—From “Table Talk.”', [I('milk', 1, '', 'Dairy & Eggs'), I('sugar', 1, '', 'Pantry'), I('nutmeg', 1, '', 'Herbs & Spices'), I('cream', 1, '', 'Dairy & Eggs')], ['When the milk turns, that is, becomes sour, smooth and thick, put it carefully into a glass dish, stand away to get very cold, dust heavily with powdered sugar, then sprinkle slightly with nutmeg and serve with sweetened cream.—From “Table Talk.”'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-24-strawberry-souffle', 'Strawberry Souffle', 'American', ["month-june", "day-24"], 'eggs', 'dessert', 45, 'Cover half a box of gelatine with half a cup of cold water and soak half an hour, then add half a cup of boiling water and stir until the gelatine is dissolved.', [I('gelatine', 0.5, 'box', 'Pantry'), I('cold water', 0.5, 'cup', 'Pantry'), I('boiling water', 0.5, 'cup', 'Pantry'), I('strawberry juice', 1, 'pint', 'Produce'), I('sugar', 0.75, 'pound', 'Pantry'), I('eggs', 6, '', 'Dairy & Eggs'), I('cream', 1, 'quart', 'Dairy & Eggs')], ['Cover half a box of gelatine with half a cup of cold water and soak half an hour, then add half a cup of boiling water and stir until the gelatine is dissolved.', 'Mix one pint of strawberry juice and three-quarters of a pound of sugar together until they form a syrup.', 'Beat the yolks of six eggs to a cream; add them to the syrup; beat until thoroughly mixed.', 'Whip one quart of cream.', 'Strain the gelatine into the syrup and eggs, turn into a freezer and freeze.', 'When frozen, stir in lightly and hastily the whipped cream.', 'Repack the freezer and stand aside for two hours.', 'This is enough for fifteen people.—“Table Talk,” Phila.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-25-strawberry-cream-pudding', 'Strawberry Cream Pudding', 'American', ["month-june", "day-25"], 'eggs', 'dessert', 45, 'Put one pint of milk in a farina boiler to scald.', [I('milk', 1, 'pint', 'Dairy & Eggs'), I('cornstarch', 4, 'even tablespoonfuls', 'Produce'), I('cold milk (a little)', 1, '', 'Dairy & Eggs'), I('granulated sugar', 0.5, 'cup', 'Pantry'), I('strawberry jelly', 0.5, 'tumbler', 'Produce'), I('eggs', 4, '', 'Dairy & Eggs'), I('sugar', 1, '', 'Pantry'), I('cream', 1, '', 'Dairy & Eggs')], ['Put one pint of milk in a farina boiler to scald.', 'Moisten four even tablespoonfuls of cornstarch with a little cold milk; stir it into the hot milk and cook until smooth and thick.', 'Add a half cup of granulated sugar and a half tumbler of strawberry jelly.', 'Beat the whites of four eggs until stiff and dry; stir them quickly into the pudding and turn out to cool.', 'Serve very cool with sugar and cream.—From “Table Talk,” Phila.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-26-strawberry-ice-cream', 'Strawberry Ice Cream', 'American', ["month-june", "day-26"], 'veg', 'dessert', 45, 'Scald one pint of cream and one pint of milk mixed.', [I('cream', 1, 'pint', 'Dairy & Eggs'), I('milk', 1, 'pint', 'Dairy & Eggs'), I('granulated sugar', 0.5, 'pound', 'Pantry'), I('ripe strawberries', 3, 'pints', 'Produce'), I('sugar', 0.5, 'pound', 'Pantry')], ['Scald one pint of cream and one pint of milk mixed.', 'Take it from the fire and dissolve in it half a pound granulated sugar.', 'Mash three pints of ripe strawberries, and strain the juice through a piece of cheese cloth.', 'Mix with it half a pound of sugar, and when it is all dissolved add it to the milk and cream.', 'When cold freeze.—From “Table Talk,” Phila.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-27-victoria-fritters', 'Victoria Fritters', 'American', ["month-june", "day-27"], 'eggs', 'dessert', 45, 'Slice a loaf of baker’s bread into pieces an inch thick; cut the slices in the centre, trimming off the crust and place them on a flat dish.', [I('baker’s bread', 1, 'loaf', 'Pantry'), I('rich milk', 1, 'quart', 'Dairy & Eggs'), I('salt', 1, 'salt spoonful', 'Herbs & Spices'), I('beaten eggs', 8, '', 'Dairy & Eggs'), I('butter', 1, '', 'Dairy & Eggs'), I('wine', 1, '', 'Pantry')], ['Slice a loaf of baker’s bread into pieces an inch thick; cut the slices in the centre, trimming off the crust and place them on a flat dish.', 'Take a quart of rich milk, one salt spoonful of salt, eight beaten eggs.', 'Stir the whole together and pour on the bread several hours before dinner, that it may be equally moistened.', 'Fry in hot butter a delicate brown, and eat with wine sauce.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-28-strawberry-sponge', 'Strawberry Sponge', 'American', ["month-june", "day-28"], 'eggs', 'dessert', 45, 'Soak half a box of gelatine in a half cup of water.', [I('gelatine', 0.5, 'box', 'Pantry'), I('water', 0.5, 'cup', 'Pantry'), I('strawberries', 1, 'quart', 'Produce'), I('sugar', 0.5, 'cupful', 'Pantry'), I('water', 1, 'cup', 'Pantry'), I('sugar', 0.5, 'cup', 'Pantry'), I('lemon (juice)', 1, '', 'Produce'), I('eggs', 4, '', 'Dairy & Eggs'), I('cream', 1, '', 'Dairy & Eggs')], ['Soak half a box of gelatine in a half cup of water.', 'Hull and mash one quart of strawberries, and sprinkle over them half a cupful of sugar.', 'Boil one cup of water and half a cup of sugar together twenty minutes, but do not boil hard.', 'Rub the berries through a fine sieve; add the soaked gelatine to the boiling syrup; take from the fire, turn into a bowl and add the berry juice; stir until the gelatine is all dissolved, add the juice of one lemon, place the bowl in a pan of crushed ice and beat with an egg beater for five minutes, add the beaten whites of four eggs and beat the whole until it begins to thicken.', 'Pour into wet moulds and set on ice to harden.', 'Serve very cold with cream.—“Table Talk.”'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-29-lalla-rookh', 'Lalla Rookh', 'American', ["month-june", "day-29"], 'veg', 'dessert', 45, 'This punch is made by the addition of half a cup of Jamaica rum to a quart of vanilla ice cream.', [I('Jamaica rum', 0.5, 'cup', 'Pantry'), I('vanilla ice cream', 1, 'quart', 'Dairy & Eggs')], ['This punch is made by the addition of half a cup of Jamaica rum to a quart of vanilla ice cream.', 'When the cream is partly frozen, remove the dasher and beat in the rum with a spoon.', 'Freeze to the consistency of an ice and serve in glasses.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
  h('ds-jun-30-currant-shortcake', 'Currant Shortcake', 'American', ["month-june", "day-30"], 'eggs', 'dessert', 45, 'Add to two cups of flour two teaspoonfuls of baking powder and one tablespoonful of granulated sugar; rub in one-half of a cup of butter and add one cup of milk, mixing quickly but thoroughly.', [I('flour', 2, 'cups', 'Pantry'), I('baking powder', 2, 'teaspoonfuls', 'Pantry'), I('granulated sugar', 1, 'tablespoonful', 'Pantry'), I('butter', 0.5, 'cup', 'Dairy & Eggs'), I('milk', 1, 'cup', 'Dairy & Eggs'), I('egg', 1, '', 'Dairy & Eggs'), I('picked currants', 1, 'quart', 'Produce'), I('sugar', 1, 'cup', 'Pantry'), I('butter', 1, '', 'Dairy & Eggs')], ['Add to two cups of flour two teaspoonfuls of baking powder and one tablespoonful of granulated sugar; rub in one-half of a cup of butter and add one cup of milk, mixing quickly but thoroughly.', 'Beat one egg lightly without separating, add to the dough, mix well and turn into greased pie tins.', 'Bake twenty minutes, or to a delicate brown, in a quick oven.', 'Mix one quart of picked currants with one cup of sugar, mash them a little and let them stand while the shortcake is baking, split and butter the cake as soon as taken from the oven.', 'Spread with the currants and serve.—From “Table Talk,” Philadelphia.'], { cal: 0, protein: 0, carbs: 0, fat: 0 }),
];
